@import url("https://fonts.googleapis.com/css2?family=Newsreader:wght@500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap");

:root {
  /* ---- Coach workstation (/admin) ----
     Same off-white / navy family as the client app, so the two halves of
     the product stop reading as different products. */
  --ink: #333333;                /* body text */
  --paper: #FAFAFA;              /* app background (centre column) */
  --paper-raised: #edf0f4;       /* left rail and right panel */
  --surface: #ffffff;            /* cards, inputs, day bodies */
  --table-head: #edf0f4;         /* table header fill */
  --logged-head: #eaeef4;        /* "what the client did" header */
  --logged-band: #f3f6fa;        /* and its column band */
  --steel: #757575;              /* dim / labels, 4.9:1 — do not lighten */
  --faint: #9E9E9E;              /* placeholder, "already added" state */
  --border: #E0E0E0;             /* hairline */
  --border-strong: #94a2b0;      /* dashed affordances */
  --accent: #00897B;
  --accent-fg: #ffffff;
  --accent-ink: #00897B;
  --accent-tint: #E0F2F1;        /* cadence pills, icon circles, demo chip */
  --accent-plate: #C62828;       /* warning / under target / destructive */
  --good: #2E7D32;               /* trained, met target, deploy */
  --good-tint: #E8F5E9;
  /* The three macros, one set of colours everywhere they are drawn: the
     coach's day targets, his logged-days table, and the client's food diary.
     They used to be picked per component and drifted apart — carbs were
     green on the targets and orange in the log. */
  --macro-protein: #334eac;
  --macro-carbs: #d99a2b;
  --macro-fat: #2e8b7a;
  /* The Draft state's tan. NOT the old cream background — this pair is the
     prototype's own colour for a programme not yet deployed. */
  --draft-bg: #f0e6cf;
  --draft-fg: #8a6d3b;

  /* Category tints (docs/UI-GUIDELINES.md §3, category pills). The training
     tint, and a lighter purple built off it for a Home card that asks the
     client to do something (upload progress pictures). */
  --cat-training-bg: #e6e4fa;
  --cat-training-fg: #3a3390;
  --cat-training-prompt-bg: #f1f0fc;
  --cat-training-prompt-border: #d9d6f5;
  --cat-training-prompt-eyebrow: #6b64ab;
  --cat-training-prompt-ink: #211d5e;
  --cat-training-prompt-rule: #e6e3f7;
  --cat-training-prompt-pending: #8b84d6;
  --cat-training-prompt-empty: #ddd9f4;
  --font-serif: "Newsreader", Georgia, serif;
  --font-sans: "Manrope", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;

  /* ---- Client app (/client): "Sand" — off-white / navy ----
     Replaces the black + lime direction. Every client-only rule below reads
     these rather than a literal, so the whole app re-themes from this block
     alone; that is what makes a light/dark pair possible later from one
     component set.

     Two rules this palette needs that the lime one didn't:
       1. The accent must stay distinct from the ink. They sit about ten
          degrees apart in hue, so anything that overlaps has to differ in
          tone too: chart strokes are --fp-accent, numerals are --fp-text.
       2. Text sitting over a chart needs a halo (see .fp-trend-overlay), or
          the trend line reads as a strikethrough through the numeral.

     Contrast was swept at AA (4.5:1) against --fp-bg. --fp-dim is 4.9:1 —
     do not lighten it. */
  --fp-bg: #FAFAFA;              /* page background, cool off-white */
  --fp-raised: #ffffff;          /* raised surface, open accordion header */
  --fp-line: #E0E0E0;            /* hairline, border, bar track */
  --fp-input: #94a2b0;           /* input / strong border */
  --fp-text: #333333;            /* body text (ink) */
  --fp-text2: #414a60;           /* secondary text */
  --fp-dim: #757575;             /* micro-labels, captions */
  --fp-accent: #00897B;          /* lines, fills, emphasis */
  --fp-accent-fg: #FAFAFA;       /* text on an accent fill */
  --fp-accent-tint: #E0F2F1;     /* goal row, icon circles, note panel */
  --fp-accent-tint-strong: #d4e0ec;
  --fp-warn: #C62828;            /* warning / destructive, 5.6:1 */

  /* Kept as an alias: older rules named the page colour "surface" back when
     it was the near-black. Same value, so both spellings are safe. */
  --fp-surface: #FAFAFA;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  /* Manrope is the typeface both designs are drawn in; this was falling back
     to the OS system font, which is the single biggest reason the admin
     didn't look like the handoff. */
  font-family: var(--font-sans);
  line-height: 1.5;
}

/* Trial: the coach admin in Archivo instead of Manrope. Scoped to pages that
   render the admin shell; on body, so dialogs portaled out of the shell get
   it too. Remove this rule to go back. */
body:has(.ad-shell) {
  --font-sans: var(--font-archivo), "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  /* Figures in the coach admin are Archivo — swept here at the token rather
     than rule by rule, because listing selectors meant every screen nobody
     had looked at yet still came out in Newsreader. A dialog title opts the
     serif back in explicitly, just below. */
  --font-serif: var(--font-sans);
}

/* The only things in the admin that are still set in Newsreader. */
body:has(.ad-shell) .pb-confirm-title,
body:has(.ad-shell) .pb-modal-title,
body:has(.ad-shell) .ad-client-title {
  font-family: "Newsreader", Georgia, serif;
}

a { color: var(--accent-ink); }

.shell {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 80px;
}

.top-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.brand {
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
  display: flex;
  align-items: center;
}

.brand-logo-img {
  height: 28px;
  width: auto;
  max-width: 160px;
  object-fit: contain;
}

.nav-links { display: flex; gap: 8px; }

.nav-links a {
  text-decoration: none;
  font-size: 0.85rem;
  padding: 6px 12px;
  border-radius: 6px;
  color: var(--steel);
}

.nav-links a.active {
  background: var(--ink);
  color: var(--paper);
}

h1 { font-size: 1.6rem; margin: 0 0 4px; }
h2 { font-size: 1.1rem; margin: 28px 0 12px; }
.subtitle { color: var(--steel); margin: 0 0 28px; font-size: 0.95rem; }

.week-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.day-card {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
  background: white;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.day-card.rest { background: var(--paper-raised); }

.day-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

/* The session title is a button until it is clicked. */
.day-name-btn { max-width: 260px; padding: 2px 6px; margin-left: -6px; border: 0; border-radius: 6px; background: none; font: inherit; font-size: 15px; font-weight: 800; color: #333333; letter-spacing: -0.01em; text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: text; }
.day-name-btn:hover { background: #F5F5F5; }
.day-name-btn.unnamed { color: #757575; }
.day-name-btn.pb-changed { background: #fff4e5; }

.day-name {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
}

.day-label-input {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 8px;
  font-size: 0.85rem;
  font-weight: 600;
}

.exercise-row {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  font-size: 0.82rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.exercise-meta { color: var(--steel); font-size: 0.76rem; }

.remove-btn {
  background: none;
  border: none;
  color: var(--accent-plate);
  cursor: pointer;
  font-size: 0.78rem;
  padding: 2px 4px;
}

.add-exercise-form {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 8px;
  border-top: 1px dashed var(--border);
}

.add-exercise-form select,
.add-exercise-form input {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 7px;
  font-size: 0.78rem;
}

.inline-row { display: flex; gap: 6px; }
.inline-row input { flex: 1; min-width: 0; }

.btn {
  background: var(--accent);
  color: var(--accent-fg);
  border: none;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 0.78rem;
  cursor: pointer;
}

.btn.secondary {
  background: var(--paper-raised);
  color: var(--ink);
  border: 1px solid var(--border);
}

.btn-sm {
  padding: 5px 8px;
  font-size: 0.7rem;
  border-radius: 5px;
}

.status-pill {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 3px 8px;
  border-radius: 999px;
  font-weight: 600;
}

.status-pill.draft { background: #f0d9c4; color: var(--accent-plate); }
.status-pill.published,
.status-pill.live { background: #E8F5E9; color: var(--good); }
.status-pill.past { background: var(--paper-raised); color: var(--steel); }

.deploy-btn {
  background: var(--good);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 10px 18px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
}

.log-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.log-item {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 0.85rem;
  display: flex;
  justify-content: space-between;
  background: white;
}

.log-item .when { color: var(--steel); font-size: 0.76rem; flex-shrink: 0; margin-left: 16px; }

.log-item a {
  color: var(--ink);
  text-decoration: none;
}

.log-item a:hover {
  color: var(--accent-ink);
  text-decoration: underline;
}

.log-item a strong {
  color: var(--accent-ink);
}

.empty-note {
  color: var(--steel);
  font-size: 0.85rem;
  font-style: italic;
}

.client-day {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 14px;
  background: white;
}

.client-exercise {
  border-top: 1px solid var(--border);
  padding-top: 10px;
  margin-top: 10px;
}

.client-exercise:first-child { border-top: none; margin-top: 0; padding-top: 0; }

.set-log-form {
  display: flex;
  gap: 6px;
  align-items: center;
  margin-top: 8px;
  flex-wrap: wrap;
}

.set-log-form input {
  width: 70px;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 7px;
  font-size: 0.8rem;
}

.logged-sets {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 12px;
  margin-top: 2px;
  white-space: nowrap;
}

.logged-weeks {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 150px;
  overflow-y: auto;
  padding-right: 4px;
}

.logged-week-group + .logged-week-group {
  border-top: 1px dashed var(--border);
  padding-top: 8px;
}

.logged-week-label {
  font-size: 0.64rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--steel);
  margin-bottom: 3px;
}

/* Reference block under an exercise name while its day is still a draft —
   last sheet's target vs. what the client actually did, one line each so
   they're easy to compare at a glance rather than run together. */
.prev-week-ref {
  border-left: 2px solid var(--border);
  padding-left: 8px;
}

.prev-week-ref .exercise-meta + .exercise-meta {
  margin-top: 2px;
}

.prev-week-ref-label {
  font-size: 0.64rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* Sets read left-to-right as a single line per logged week instead of
   stacking — the row's height no longer grows with how many sets a
   client logs. Overflow scrolls with the rest of the table via the
   existing .exercise-table-wrap horizontal scroll. */
.set-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-size: 0.72rem;
  font-family: ui-monospace, monospace;
}

.set-chip + .set-chip {
  border-left: 1px solid var(--border);
  padding-left: 12px;
}

/* ---- Program builder: horizontal spreadsheet layout ---- */

/* Collapsible per-day container for the program builder — mirrors the
   client Training tab's day cards so the coach gets the same scannable
   list instead of 7 always-open tables. Rest days collapse by default
   (nothing to see until the coach wants to add something); built days
   default open since the coach is usually there to edit them. */
.admin-day-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: white;
  /* clip, not hidden: hidden makes the card a scroll container and the
     pending-changes bar would then stick to the card instead of the page. */
  overflow: clip;
}

.admin-day-card + .admin-day-card {
  margin-top: 10px;
}

.admin-day-card.rest {
  background: var(--paper-raised);
}

/* An open session carries a navy stripe down its left edge, as an open past
   meeting does. Drawn on top rather than as an inset shadow, because the
   tinted header and the exercise table would paint over a shadow. */
.admin-day-card.open {
  position: relative;
}

.admin-day-card.open::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  background: #1E3A5F;
  z-index: 2;
  pointer-events: none;
}

/* Session headers carry the accent tint, like the card headers elsewhere. */
.admin-day-card-toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: #E0F2F1;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
}

.admin-day-card-toggle:hover {
  background: #dce4ee;
}

.admin-day-card-head-left {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
}

.admin-day-card-head-left .day-name {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
  min-width: 34px;
  flex-shrink: 0;
}

.admin-day-card-head-left .inline-row {
  flex: 1;
  max-width: 280px;
}

/* The session's title is not a field any more: it sizes to the name, so the
   summary beside it is not pushed across the card. */
.admin-day-card-head-left .inline-row.day-name {
  flex: 0 1 auto;
  max-width: 340px;
  min-width: 0;
}

.admin-day-card-head-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  margin-left: auto;
}

.admin-day-summary {
  font-size: 0.8rem;
  font-weight: 800;
  color: var(--ink);
  white-space: nowrap;
}
/* Rest and empty days keep the quiet grey; only a built day is loud. */
.admin-day-card.rest .admin-day-summary { font-weight: 600; color: var(--steel); }

.admin-day-chevron-btn {
  border: none;
  background: none;
  padding: 2px;
  cursor: pointer;
  display: flex;
  color: var(--steel);
}

.admin-day-chevron {
  display: flex;
  transition: transform 0.15s ease;
}

.admin-day-chevron.open {
  transform: rotate(180deg);
}

.admin-day-card-body {
  /* the table inside brings its own padding via .exercise-table-wrap */
}

.exercise-table-wrap {
  overflow-x: auto;
}

.exercise-table,
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

.exercise-table th,
.data-table th {
  text-align: left;
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--steel);
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.exercise-table td,
.data-table td {
  padding: 7px 10px;
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
  vertical-align: middle;
  white-space: nowrap;
}

.exercise-table th:last-child,
.exercise-table td:last-child,
.data-table th:last-child,
.data-table td:last-child {
  border-right: none;
}

/* Marks the boundary between what the coach set and what the client
   actually did — a heavier rule than the plain column grid so the two
   read as visually distinct at a glance. */
.exercise-table th.logged-col,
.exercise-table td.logged-col {
  border-left: 1px solid var(--border);
}

.exercise-table tbody tr:last-child td,
.data-table tbody tr:last-child td {
  border-bottom: none;
}

.exercise-name-cell {
  font-weight: 600;
  white-space: normal;
  min-width: 140px;
}

.notes-cell {
  color: var(--steel);
  white-space: normal;
  max-width: 220px;
}

.add-exercise-row td {
  background: var(--paper);
  padding: 6px 6px;
}

/* "Also add to the remaining weeks" under the exercise picker on the add row. */
.pb-apply-weeks {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 6px;
  font-size: 10.5px;
  color: var(--steel);
  cursor: pointer;
  white-space: nowrap;
}

/* The table's input rule would stretch the box to the full cell width and
   push the label away; keep it a plain 14px checkbox beside its text. */
.pb .exercise-table .pb-apply-weeks input,
.pb-apply-weeks input {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  accent-color: var(--accent);
}

/* There is no bin / Add column any more: a row's bin and "+ Add" sit at the
   end of its last cell (.pb-cell-end). The rules that pinned and narrowed
   the table's LAST cell went with it — left behind, they squeezed "What the
   client did" to 30px and pinned it, so the table could not scroll to it. */

.exercise-table input,
.exercise-table select,
.data-table input,
.data-table select {
  width: 100%;
  min-width: 64px;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 5px 6px;
  font-size: 0.78rem;
}

/* ---- Nutrition panel ---- */

.nutrition-panel {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nutrition-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  padding: 14px 16px;
  margin-bottom: 22px;
  background: var(--paper-raised);
  border: 1px solid var(--border);
  border-radius: 8px;
}

.inline-number-input {
  width: 90px;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 4px 6px;
  font-size: 0.85rem;
  font-weight: 600;
}

.nutrition-table-wrap {
  margin-bottom: 22px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
}

.nutrition-table-wrap h3 {
  font-size: 0.85rem;
  margin: 0 0 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.computed-cell {
  color: var(--steel);
  font-family: ui-monospace, monospace;
}

.totals-cell {
  font-weight: 700;
  font-family: ui-monospace, monospace;
}

.coach-notes-textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  font-size: 0.85rem;
  font-family: inherit;
  resize: vertical;
}

.add-exercise-row .btn {
  width: auto;
  white-space: nowrap;
}

.tracker-category-row {
  background: var(--paper-raised) !important;
  font-weight: 700;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--steel);
}

/* Daily/Weekly Tracker Overview: metric names stay pinned on the left as the
   coach scrolls sideways through weeks/days — same "frozen column" idea as a
   spreadsheet, since a client can accumulate far more periods than fit on
   screen at once. */
.tracker-metric-col {
  position: sticky;
  left: 0;
  z-index: 2;
  background: white;
  box-shadow: 1px 0 0 0 var(--border);
  min-width: 160px;
}

.tracker-overview-table thead .tracker-metric-col {
  z-index: 3;
}

/* ---- Progress pictures ---- */

.photo-gallery {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Collapsed-by-default accordion row: one period's photos + coach notes.
   Collapsed it's just a title/subtitle/chevron bar, so a long history costs
   almost no vertical space until a specific check-in is opened. */
.photo-period-row {
  border: 1px solid var(--border);
  border-radius: 10px;
  background: white;
  overflow: hidden;
}

.photo-period-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: none;
  background: none;
  padding: 12px 14px;
  cursor: pointer;
  text-align: left;
}

.photo-period-header:hover {
  background: var(--paper-raised);
}

.photo-period-heading {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.photo-period-title {
  font-size: 0.86rem;
  font-weight: 700;
}

.photo-period-subtitle {
  font-size: 0.74rem;
  color: var(--steel);
}

.photo-period-chevron {
  flex: 0 0 auto;
  display: flex;
  color: var(--steel);
  transition: transform 0.15s ease;
}

.photo-period-chevron.open {
  transform: rotate(180deg);
}

.photo-period-body {
  padding: 4px 14px 16px;
  border-top: 1px dashed var(--border);
}

.photo-period-body .photo-slot-grid {
  margin-top: 14px;
}

.photo-note-form {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.photo-note-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--steel);
}

.photo-note-field textarea {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 7px 9px;
  font-size: 0.84rem;
  font-family: inherit;
  font-weight: 400;
  color: var(--ink, #222);
  resize: vertical;
}

.photo-note-form .btn {
  align-self: flex-start;
}

.photo-note-readonly {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.photo-note-readonly-label {
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--steel);
  margin-bottom: 2px;
}

.photo-note-readonly-text {
  font-size: 0.86rem;
  white-space: pre-wrap;
}

.photo-slot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 12px;
}

.photo-thumb-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.photo-thumb-img {
  width: 100%;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--paper-raised);
}

.photo-thumb-empty {
  width: 100%;
  aspect-ratio: 3 / 4;
  border-radius: 8px;
  border: 1px dashed var(--border);
  background: var(--paper-raised);
  color: var(--steel);
  font-size: 0.72rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 6px;
}

.photo-thumb-label {
  font-size: 0.76rem;
  font-weight: 600;
  text-align: center;
}

/* ---- Progress pictures: compare any two check-ins side by side ---- */

.photo-compare-controls {
  display: flex;
  gap: 16px;
  margin-bottom: 18px;
}

.photo-compare-controls label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.78rem;
  color: var(--steel);
}

.photo-compare-controls select {
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: white;
  font-size: 0.85rem;
  color: var(--ink);
}

.photo-compare-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.photo-compare-pair {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.photo-compare-slot-label {
  font-size: 0.8rem;
  font-weight: 700;
}

.photo-compare-images {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.photo-upload-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.photo-upload-tile {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 3 / 4;
  border-radius: 10px;
  border: 2px dashed var(--border);
  background: var(--paper-raised);
  cursor: pointer;
  overflow: hidden;
}

.photo-upload-tile .photo-thumb-img {
  border: none;
  border-radius: 0;
}

.photo-upload-plus {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--steel);
}

.photo-upload-input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
  width: 100%;
  height: 100%;
}

/* ---- Admin: Progress pictures tab (pp-*) ----
   Colours, radii and spacing from docs/UI-GUIDELINES.md. Colour means
   something here: #00897B for selection and filled dots, grey for incomplete
   or paused. No orange on this tab. */

.pp { display: flex; flex-direction: column; gap: 18px; }
.pp-head { display: flex; flex-direction: column; gap: 4px; }
.pp-eyebrow { font-size: 11px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: #757575; }
.pp-summary { font-size: 12.5px; font-weight: 500; color: #9E9E9E; font-variant-numeric: tabular-nums; }

.pp-card { background: #fff; border: 1px solid #E0E0E0; border-radius: 12px; }
.pp-label { font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #757575; }
.pp-label-block { display: block; margin-bottom: 10px; }
.pp-label-row { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.pp-label-right { font-size: 12px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.pp-faint { font-size: 12px; font-weight: 500; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.pp-hairline { border: 0; border-top: 1px solid #EEEEEE; margin: 18px 0; }

.pp-btn { display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: 8px; padding: 10px 14px; font: inherit; font-size: 13px; font-weight: 700; text-decoration: none; cursor: pointer; white-space: nowrap; }
.pp-btn.sm { padding: 6px 12px; }
.pp-btn.navy { background: #1E3A5F; color: #fff; }
.pp-btn.tint { background: #E0F2F1; color: #1E3A5F; }
.pp-btn:disabled { opacity: 0.6; cursor: default; }
.pp-input { width: 160px; padding: 6px 10px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; font: inherit; font-size: 13px; font-weight: 500; color: #333333; }
.pp-select { padding: 6px 10px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; font: inherit; font-size: 13px; font-weight: 700; color: #333333; cursor: pointer; }
.pp-input:focus, .pp-select:focus { outline: none; border-color: #00897B; }

.pp-seg { display: inline-flex; gap: 4px; padding: 4px; background: #F5F5F5; border-radius: 8px; }
.pp-seg-btn { border: 0; background: transparent; border-radius: 6px; padding: 6px 12px; font: inherit; font-size: 12px; font-weight: 800; color: #757575; cursor: pointer; white-space: nowrap; }
.pp-seg-btn:hover { color: #333333; }
.pp-seg-btn.active { background: #fff; color: #333333; box-shadow: 0 1px 2px rgba(51, 51, 51, 0.12); }
.pp-seg-btn:focus-visible { outline: 2px solid #00897B; outline-offset: 2px; }

/* Schedule + angles card */
.pp-config { padding: 18px 22px; }
.pp-schedule { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; }
.pp-schedule-word { font-size: 13px; font-weight: 600; color: #333333; }
.pp-date { width: auto; font-variant-numeric: tabular-nums; }
.pp-hint { margin: 10px 0 0; font-size: 12px; font-weight: 500; color: #9E9E9E; line-height: 1.45; font-variant-numeric: tabular-nums; }
.pp-foot { margin: 12px 0 0; font-size: 12px; font-weight: 500; color: #9E9E9E; line-height: 1.45; }
/* The coach's note on how to take the pictures, shown on the client's sheet. */
.pp-instructions { display: block; margin-top: 14px; }
.pp-instructions-box { display: block; width: 100%; box-sizing: border-box; padding: 8px 10px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; font: inherit; font-size: 13px; font-weight: 500; line-height: 1.45; color: #333333; resize: vertical; }
.pp-instructions-box:focus { outline: none; border-color: #00897B; }
.pp-instructions-box::placeholder { color: #BDBDBD; }
/* Save for the schedule: nothing reaches the client until it is pressed. */
.pp-save-row { display: flex; align-items: center; justify-content: flex-end; flex-wrap: wrap; gap: 10px; margin-top: 14px; }
.pp-save-status { margin-right: auto; font-size: 12px; font-weight: 600; color: #9E9E9E; }
.pp-save-row.dirty .pp-save-status { color: #C62828; }
.pp-btn.ghost { background: #fff; border: 1px solid #E0E0E0; color: #333333; }

/* Angle chips */
.pp-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.pp-chip { display: inline-flex; align-items: center; gap: 4px; border: 1px solid #cfdce9; border-radius: 6px; background: #E0F2F1; color: #1E3A5F; }
.pp-chip.paused { border-color: #E0E0E0; background: #F5F5F5; color: #757575; }
.pp-chip[draggable="true"] { cursor: grab; }
.pp-chip.dragging { opacity: 0.6; }
.pp-chip.editing { gap: 6px; padding: 4px 4px 4px 11px; }
.pp-chip-toggle { display: inline-flex; align-items: center; gap: 8px; border: 0; background: none; color: inherit; font: inherit; padding: 7px 4px 7px 11px; cursor: pointer; }
.pp-chip-dot { flex: none; width: 6px; height: 6px; border-radius: 999px; background: #00897B; }
.pp-chip.paused .pp-chip-dot { background: #9E9E9E; }
.pp-chip-name { font-size: 13px; font-weight: 800; }
.pp-chip-state { font-size: 10px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; }
.pp-chip-more { border: 0; background: none; color: inherit; font: inherit; font-size: 14px; font-weight: 800; line-height: 1; padding: 7px 11px 7px 4px; cursor: pointer; }
.pp-chip-more:hover, .pp-chip-toggle:hover .pp-chip-name { color: #333333; }
.pp-chip-form { display: inline-flex; align-items: center; gap: 6px; }
.pp-chip-input { width: 140px; padding: 4px 8px; border: 1px solid #E0E0E0; border-radius: 6px; background: #fff; font: inherit; font-size: 13px; font-weight: 600; color: #333333; }
.pp-chip-input:focus { outline: none; border-color: #00897B; }
.pp-chip-act { border: 0; border-radius: 6px; background: none; padding: 4px 6px; font: inherit; font-size: 12px; font-weight: 800; color: #1E3A5F; cursor: pointer; }
.pp-chip-act:hover { background: #fff; }
.pp-chip-act.danger { color: #C62828; }
.pp-chip-act.danger:hover { background: #fbeaea; }
.pp-add { display: inline-flex; align-items: center; gap: 8px; }
/* Its own row above the angle pills, so new angles never push it along. */
.pp-add-row { display: flex; margin-bottom: 12px; }

/* Gallery card */
.pp-gallery { overflow: hidden; }
.pp-gallery-head { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 14px 22px; background: #E0F2F1; }
/* On the accent-tint band: navy title, white toggles, an active one outlined in navy. */
.pp-gallery-head .pp-eyebrow { color: #1E3A5F; }
.pp-gallery-head .pp-gallery-help { color: #757575; }
.pp-gallery-head .pp-compare-btn.active { background: #fff; border-color: #1E3A5F; color: #1E3A5F; }
/* The settings card's header band, flush with the card's edges. */
.pp-config-head { display: flex; flex-direction: column; gap: 3px; margin: -18px -22px 18px; padding: 14px 22px; border-radius: 12px 12px 0 0; background: #E0F2F1; }
.pp-config-head .pp-eyebrow { color: #1E3A5F; }
.pp-config-head .pp-summary { color: #757575; }
.pp-gallery-help { margin: 4px 0 0; font-size: 12.5px; font-weight: 500; color: #9E9E9E; }
.pp-compare-btn { display: inline-flex; align-items: center; gap: 8px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; color: #757575; padding: 8px 12px; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; white-space: nowrap; }
.pp-compare-btn:hover { color: #333333; }
.pp-compare-btn.active { background: #E0F2F1; border-color: #cfdce9; color: #1E3A5F; }

/* Sheets as rows that fold open, one per sheet, like the days in Training. */
.pp-sheet-list { display: flex; flex-direction: column; gap: 10px; padding: 14px 22px 22px; border-top: 1px solid #EEEEEE; background: #FAFAFA; }
.pp-sheet-row { overflow: hidden; border: 1px solid #E0E0E0; border-radius: 12px; background: #fff; }
.pp-sheet-row.open { border-color: #cfdce9; }
.pp-sheet-row-head { display: flex; align-items: center; gap: 14px; width: 100%; padding: 12px 18px; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.pp-sheet-row-head { background: #E0F2F1; }
.pp-sheet-row-head:hover { background: #dce4ee; }
.pp-sheet-row-head .pp-sheet-row-meta,
.pp-sheet-row-head .pp-tile-badge:not(.open) { color: #757575; }
.pp-sheet-row-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.pp-sheet-row-titlerow { display: flex; align-items: baseline; gap: 10px; }
.pp-sheet-row-title { font-size: 14px; font-weight: 800; color: #333333; }
.pp-sheet-row-meta { font-size: 12px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.pp-sheet-row-phases { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; min-width: 0; }
.pp-sheet-row-body { padding: 18px; border-top: 1px solid #EEEEEE; }
.pp-chevron { flex: none; display: flex; color: #9E9E9E; transition: transform 0.15s ease; }
.pp-chevron.open { transform: rotate(180deg); }
.pp-compare-view { border-top: 1px solid #EEEEEE; }
.pp-detail-side .pp-btn.tint.sm { margin-bottom: 12px; }

/* Week rail */
.pp-gallery-tools { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; }
.pp-tools-label { font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #9E9E9E; }
.pp-seg-btn:disabled { color: #BDBDBD; cursor: default; }
.pp-rail { overflow-x: auto; padding: 14px 22px; background: #FAFAFA; border-top: 1px solid #EEEEEE; border-bottom: 1px solid #EEEEEE; scrollbar-width: thin; }
.pp-rail-inner { display: inline-flex; flex-direction: column; gap: 8px; min-width: 100%; }
.pp-rail-tiles, .pp-phase-row { display: flex; gap: 10px; }
/* A plan phase spanning the weeks it covered, in the Plan tab's track tints */
.pp-phase { flex: none; box-sizing: border-box; padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pp-phase.nutrition { background: #dff1ef; color: #1d7a70; }
.pp-phase.training { background: #e6e4fa; color: #3a3390; }
.pp-phase.none { background: transparent; }
.pp-tile { flex: 0 0 132px; display: flex; flex-direction: column; gap: 8px; box-sizing: border-box; padding: 10px 12px; border: 1px solid #E0E0E0; border-radius: 10px; background: #fff; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.pp-tile:hover { border-color: #cfdce9; }
.pp-tile.selected { border-color: #1E3A5F; box-shadow: 0 0 0 2px #E0F2F1; }
.pp-tile-top { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
.pp-tile-title { font-size: 13px; font-weight: 800; color: #333333; white-space: nowrap; }
.pp-tile-badge { font-size: 10px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #9E9E9E; }
.pp-tile-badge.open { color: #00897B; }
.pp-tile-foot { display: flex; justify-content: space-between; gap: 6px; font-size: 11px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }

/* Viewer */
.pp-view { padding: 18px 22px 22px; }
.pp-view-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; flex-wrap: wrap; margin-bottom: 16px; }
.pp-view-titles { min-width: 0; }
.pp-view-titlerow { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.pp-view-title { font-size: 16px; font-weight: 800; color: #333333; }
.pp-view-meta { margin-top: 4px; font-size: 12.5px; font-weight: 500; color: #757575; font-variant-numeric: tabular-nums; }
.pp-view-selects, .pp-view-select { display: flex; align-items: center; gap: 8px; }
.pp-compare-vs { font-size: 12px; font-weight: 700; color: #9E9E9E; }
.pp-pill { display: inline-block; border-radius: 999px; padding: 4px 10px; font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.pp-pill.open { background: #E0F2F1; color: #00897B; }
/* Any photo frame whose photo is not there */
.pp-hole { display: flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px dashed #E0E0E0; background: #FAFAFA; font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #9E9E9E; }
/* The frame classes set display:block; an empty frame still centres its label. */
.pp-hole.pp-shot-img, .pp-hole.pp-detail-frame, .pp-hole.pp-pair-frame { display: flex; }

/* Viewer: the sheet */
.pp-shots { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 14px; }
.pp-shot { display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: zoom-in; }
.pp-shot-img { display: block; width: 100%; aspect-ratio: 3 / 4; object-fit: cover; border-radius: 10px; background: #FAFAFA; }
.pp-shot:focus-visible .pp-shot-img { outline: 2px solid #00897B; outline-offset: 2px; }
.pp-shot-cap { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.pp-shot-name { font-size: 12.5px; font-weight: 800; color: #333333; }
.pp-shot-date { font-size: 11px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.pp-notes { margin-top: 22px; padding-top: 18px; border-top: 1px solid #EEEEEE; }
.pp-notes-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.pp-notes-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 14px; }
.pp-note-field { display: flex; flex-direction: column; gap: 4px; }
.pp-note-label { font-size: 12px; font-weight: 800; color: #333333; }
.pp-note-field textarea { width: 100%; box-sizing: border-box; padding: 8px 10px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; font: inherit; font-size: 13px; font-weight: 500; line-height: 1.45; color: #333333; resize: vertical; }
.pp-note-field textarea:focus { outline: none; border-color: #00897B; }
.pp-notes-foot { display: flex; justify-content: flex-end; gap: 8px; margin-top: 14px; }
/* Saved notes, locked until Edit: read-only boxes and a green saved line. */
.pp-notes-saved { font-size: 12px; font-weight: 800; color: #2E7D32; font-variant-numeric: tabular-nums; }
.pp-note-read { margin: 0; min-height: 66px; box-sizing: border-box; padding: 8px 10px; border: 1px solid #EEEEEE; border-radius: 8px; background: #FAFAFA; font-size: 13px; font-weight: 500; line-height: 1.45; color: #333333; white-space: pre-wrap; overflow-wrap: anywhere; }
.pp-note-read.empty { color: #BDBDBD; }

/* Viewer: one photo */
.pp-detail { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 22px; }
.pp-detail-shot { flex: 0 1 480px; min-width: 240px; display: flex; flex-direction: column; gap: 10px; }
.pp-detail-frame { display: block; width: 100%; aspect-ratio: 3 / 4; border-radius: 12px; overflow: hidden; background: #FAFAFA; }
.pp-detail-frame img { display: block; width: 100%; height: 100%; object-fit: cover; }
.pp-detail-nav { display: flex; align-items: center; justify-content: center; gap: 14px; }
.pp-icon-btn { width: 32px; height: 32px; border: 1px solid #E0E0E0; border-radius: 8px; background: #fff; color: #333333; font: inherit; font-size: 14px; font-weight: 800; cursor: pointer; }
.pp-icon-btn:hover { border-color: #cfdce9; color: #333333; }
.pp-detail-side { flex: 1 1 260px; min-width: 0; }
.pp-detail-name { margin: 0; font-size: 22px; font-weight: 800; color: #333333; }
.pp-detail-when { margin: 4px 0 0; font-size: 13px; font-weight: 600; color: #757575; font-variant-numeric: tabular-nums; }
.pp-detail-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.pp-detail-side .pp-hairline { margin: 18px 0 12px; }
.pp-strip { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.pp-detail-side .pp-label + .pp-strip { margin-top: 10px; }
.pp-mini { display: block; width: 62px; aspect-ratio: 3 / 4; box-sizing: border-box; padding: 0; border: 0; border-radius: 6px; overflow: hidden; background: #FAFAFA; cursor: pointer; }
.pp-mini img { display: block; width: 100%; height: 100%; object-fit: cover; }
.pp-mini.current { box-shadow: 0 0 0 2px #1E3A5F; }
.pp-mini-hole { display: block; width: 100%; height: 100%; box-sizing: border-box; border: 1px dashed #E0E0E0; border-radius: 6px; }
.pp-mini-wrap { display: flex; flex-direction: column; gap: 4px; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
.pp-mini-label { font-size: 11px; font-weight: 700; color: #757575; text-align: center; font-variant-numeric: tabular-nums; }

/* Viewer: compare one angle at two weeks */
.pp-compare-tools { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; margin-bottom: 16px; }
.pp-size-tools { display: flex; align-items: center; gap: 10px; }
.pp-angle-row { display: flex; flex-wrap: wrap; gap: 8px; }
.pp-angle-btn { border: 1px solid #E0E0E0; border-radius: 6px; background: #fff; color: #757575; padding: 7px 11px; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; }
.pp-angle-btn:hover { color: #333333; }
.pp-angle-btn.active { border-color: #cfdce9; background: #E0F2F1; color: #1E3A5F; }
.pp-pair { display: flex; flex-wrap: wrap; justify-content: center; gap: 14px; }
.pp-pair-side { flex: 1 1 220px; min-width: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
.pp-pair-frame { display: block; aspect-ratio: 3 / 4; border-radius: 10px; overflow: hidden; background: #FAFAFA; }
.pp-pair-frame img { display: block; width: 100%; height: 100%; object-fit: cover; }
.pp-pair-cap { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.pp-pair-title { font-size: 13.5px; font-weight: 800; color: #333333; }
.pp-pair-cap.accent .pp-pair-title { color: #00897B; }
.pp-pair-shot { font-size: 12px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }

/* Empty states (they stand in for the gallery; the schedule card stays) */
.pp-empty { padding: 18px 22px; }
.pp-empty-title { margin: 0; font-size: 16px; font-weight: 800; color: #333333; }
.pp-empty-text { margin: 6px 0 0; max-width: 62ch; font-size: 13px; font-weight: 500; line-height: 1.5; color: #757575; }
.pp-suggest { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.pp-suggest-chip { border: 0; border-radius: 6px; background: #E0F2F1; color: #00897B; padding: 7px 11px; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; }
.pp-suggest-chip:hover { color: #1E3A5F; }

/* ---- Admin panel ---- */

.admin-shell {
  min-height: 100vh;
}

.admin-body {
  display: grid;
  grid-template-columns: 240px 1fr;
  max-width: 1400px;
  margin: 0 auto;
}

.admin-sidebar {
  padding: 24px 16px;
  border-right: 1px solid var(--border);
  min-height: calc(100vh - 57px);
  position: sticky;
  top: 0;
  align-self: start;
  height: 100vh;
  overflow-y: auto;
}

.feed-nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  margin-bottom: 18px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 600;
  border: 1px solid var(--border);
  background: white;
}

.feed-nav-btn:hover {
  background: var(--paper-raised);
}

.feed-nav-btn.active {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}

.feed-nav-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.conflict-badge {
  margin-left: auto;
  background: var(--accent-plate);
  color: white;
  font-size: 0.68rem;
  font-weight: 700;
  border-radius: 999px;
  padding: 1px 7px;
  line-height: 1.5;
}

.conflict-banner {
  border: 1px solid var(--accent-plate);
  background: #fbeee6;
  border-radius: 10px;
  padding: 12px 16px;
  color: var(--accent-plate);
}

.conflict-banner strong {
  color: var(--accent-plate);
}

.conflict-banner ul {
  margin: 8px 0 0;
  padding-left: 18px;
}

.conflict-banner li {
  margin-bottom: 4px;
  font-size: 0.85rem;
}

.conflict-tag {
  background: var(--accent-plate);
  color: white;
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: 6px;
  padding: 2px 6px;
}

.calendar-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 6px;
}

.calendar-nav {
  display: flex;
  align-items: center;
  gap: 10px;
}

.calendar-nav-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--paper);
  color: var(--ink);
  text-decoration: none;
  font-size: 1.1rem;
  line-height: 1;
}

.calendar-nav-btn:hover {
  background: var(--paper-raised);
}

.calendar-month-label {
  font-weight: 700;
  font-size: 0.95rem;
  min-width: 140px;
  text-align: center;
}

.calendar-today-btn {
  text-decoration: none;
  font-size: 0.8rem;
  padding: 6px 12px;
}

.calendar-grid {
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: var(--border);
  box-shadow: 0 1px 2px rgba(20, 23, 28, 0.04);
}

.calendar-grid-head {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  background: var(--border);
}

.calendar-weekday {
  padding: 9px 10px;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
  background: var(--paper-raised);
}

.calendar-grid-row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  background: var(--border);
}

.calendar-grid-row + .calendar-grid-row {
  margin-top: 1px;
}

.calendar-grid-head {
  margin-bottom: 1px;
}

.calendar-cell {
  background: #f6f5f0;
  min-height: 110px;
  padding: 7px 7px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: background-color 0.1s ease;
}

.calendar-cell.outside {
  background: var(--paper-raised);
}

.calendar-cell.outside .calendar-cell-date {
  color: #b6b9ae;
}

.calendar-cell.today {
  background: #e9eff3;
}

/* The day open in the right-hand panel: same frosted blue as the selected
   week on the builder rail. */
.calendar-cell.selected {
  background: color-mix(in srgb, var(--accent) 16%, rgba(255, 255, 255, 0.55));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 55%, transparent);
}

.calendar-cell { position: relative; cursor: pointer; }
.calendar-cell:hover { background: #F5F5F5; }
.calendar-cell.selected:hover { background: color-mix(in srgb, var(--accent) 20%, rgba(255, 255, 255, 0.55)); }

/* Stretched link covering the cell; date and chips sit above it. */
.calendar-cell-link { position: absolute; inset: 0; z-index: 0; border-radius: inherit; }
.calendar-cell-date, .calendar-cell-meetings { position: relative; z-index: 1; }
.calendar-cell-date { pointer-events: none; }

/* An entry in the day panel with its delete control alongside. */
.cd-entry-wrap { display: flex; align-items: stretch; gap: 4px; }
.cd-entry-wrap > .cd-entry { flex: 1; min-width: 0; }
.cd-entry-delete { display: flex; align-items: center; opacity: 0; transition: opacity 120ms ease; }
.cd-entry-wrap:hover .cd-entry-delete, .cd-entry-delete:focus-within { opacity: 1; }
.cd-entry-delete .row-icon-btn { width: 22px; height: 22px; border-radius: 6px; }
.cd-entry-delete .row-icon-btn svg { width: 11px; height: 11px; }

/* Saved-state button in a panel head. It is a status, not an action:
   "Saving…" while a form is in flight, "All saved" otherwise. */
.pb-autosave-btn {
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
  color: var(--steel);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: default;
}
.pb-autosave-btn.saved { color: var(--good); border-color: color-mix(in srgb, var(--good) 45%, transparent); }
.pb-autosave-btn.saving { color: var(--accent); border-color: var(--accent); }

/* ---- Calendar day panel: hour rows with entries and a + per hour ---- */
.cd-head { margin-bottom: 12px; }
.cd-kicker {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--steel);
}
.cd-title { margin: 2px 0 0; font-family: inherit; font-size: 1.15rem; font-weight: 800; letter-spacing: -0.01em; color: var(--ink); }
.cd-sub { margin-top: 3px; font-size: 11px; color: var(--steel); }

.cd-timeline { display: flex; flex-direction: column; }
.cd-outside { display: flex; flex-direction: column; gap: 4px; margin-bottom: 8px; }

/* Quarter-hour grid: hour rows are absolutely stacked, each holding four
   slot buttons; entries float in a layer above, sized by their length. */
.cd-grid { position: relative; border-top: 1px solid var(--border); }

.cd-hour-row { position: absolute; left: 0; right: 0; display: flex; }

.cd-hour-label {
  flex: 0 0 40px;
  padding-top: 3px;
  font-size: 10px;
  font-weight: 700;
  color: var(--steel);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.cd-quarters { flex: 1; display: flex; flex-direction: column; min-width: 0; }

.cd-quarter {
  flex: 1;
  border: 0;
  border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent);
  background: transparent;
  padding: 0;
  cursor: pointer;
}
.cd-quarter:last-child { border-bottom: 1px solid var(--border); }
.cd-quarter:hover { background: color-mix(in srgb, var(--accent) 10%, transparent); }
.cd-quarter:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

.cd-events { position: absolute; top: 0; bottom: 0; left: 40px; right: 0; pointer-events: none; }
.cd-event { position: absolute; box-sizing: border-box; padding: 1px 3px 1px 0; pointer-events: auto; }
.cd-event .cd-entry-wrap, .cd-event .cd-entry { height: 100%; }
.cd-event .cd-entry { overflow: hidden; }

.cd-entry {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 6px 8px;
  border-radius: 7px;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--ink);
  text-decoration: none;
  font-size: 11px;
}
.cd-entry.own { border-style: dashed; border-color: var(--border); background: var(--surface); }
.cd-entry.done { opacity: 0.6; }
a.cd-entry:hover { border-color: var(--accent); }

.cd-entry-time { flex: 0 0 auto; display: flex; flex-direction: column; font-weight: 800; font-variant-numeric: tabular-nums; }
.cd-entry-time em { font-style: normal; font-weight: 500; font-size: 9.5px; color: var(--steel); }
.cd-entry-text { display: flex; flex-direction: column; min-width: 0; }
.cd-entry-who { font-weight: 700; }
.cd-entry-topic { color: var(--steel); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.cd-entry.compact { padding: 0 6px; align-items: center; }
.cd-entry-line { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; }
.cd-entry-line strong { font-variant-numeric: tabular-nums; }

/* Clear the panel's collapse arrow, which sits over the top-left corner. */
.cd-head { padding-left: 18px; }

.cd-form { display: flex; flex-direction: column; gap: 10px; margin-top: 10px; }
.cd-form-row { display: flex; gap: 10px; }
.cd-form-row > * { flex: 1; }
.cd-form input, .cd-form select {
  width: 100%;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
  color: var(--ink);
  padding: 0 8px;
  font: inherit;
  font-size: 13px;
}

.calendar-cell-date {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--steel);
  padding: 2px 4px;
}

.calendar-cell.today .calendar-cell-date {
  color: var(--accent-ink);
}

.calendar-cell-meetings {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.calendar-chip {
  display: flex;
  align-items: baseline;
  gap: 4px;
  padding: 2px 5px;
  border-radius: 5px;
  background: var(--paper-raised);
  text-decoration: none;
  color: var(--ink);
  font-size: 0.7rem;
  overflow: hidden;
  white-space: nowrap;
}

.calendar-chip:hover {
  background: var(--border);
}

.calendar-chip-time {
  font-weight: 700;
  flex-shrink: 0;
}

.calendar-chip-name {
  overflow: hidden;
  text-overflow: ellipsis;
}

.calendar-chip.conflict {
  background: #fbeee6;
  color: var(--accent-plate);
}

.calendar-chip.completed {
  opacity: 0.55;
}

.calendar-chip-more {
  font-size: 0.68rem;
  color: var(--steel);
  padding: 0 5px;
}

@media (max-width: 900px) {
  .calendar-cell {
    min-height: 80px;
  }
  .calendar-chip-name {
    display: none;
  }
}

.sidebar-heading {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
  margin-bottom: 12px;
}

.client-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 18px;
}

.client-list-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--ink);
  font-size: 0.9rem;
}

.client-list-item:hover {
  background: var(--paper-raised);
}

.client-list-item.active {
  background: var(--ink);
  color: var(--paper);
}

.client-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-fg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 700;
  flex-shrink: 0;
}

.client-list-item.active .client-avatar {
  background: var(--paper);
  color: var(--ink);
}

.new-client-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 14px;
  border-top: 1px dashed var(--border);
}

.new-client-form input {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 8px;
  font-size: 0.82rem;
}

.admin-main {
  padding: 28px 32px 80px;
  /* Grid items default to min-width: auto, which lets wide content (like the
     Tracker's frozen-column table) stretch the whole page instead of
     scrolling within its own wrapper. min-width: 0 lets this column shrink
     to the grid track and pushes overflow down to .exercise-table-wrap. */
  min-width: 0;
}

.client-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  padding-bottom: 22px;
  margin-bottom: 22px;
  border-bottom: 1px solid var(--border);
}

.client-header h1 {
  margin-bottom: 14px;
}

.client-stat-row {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
}

.client-stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.stat-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
}

.stat-value {
  font-size: 0.88rem;
  font-weight: 600;
}

.measurement-summary-row {
  background: var(--paper-raised);
  font-weight: 600;
}

.measurement-summary-row td {
  border-top: 2px solid var(--border);
}

.measurement-summary-row .change-up {
  color: #C62828;
}

.measurement-summary-row .change-down {
  color: #2E7D32;
}

.change-stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.change-stat .stat-value.change-up {
  color: #C62828;
}

.change-stat .stat-value.change-down {
  color: #2E7D32;
}

.snapshot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 14px;
}

.snapshot-card {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  background: var(--paper-raised);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.snapshot-card h4 {
  margin: 0;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--steel);
}

.snapshot-card .snapshot-main {
  font-size: 1.15rem;
  font-weight: 700;
}

.snapshot-card .snapshot-sub {
  font-size: 0.78rem;
  color: var(--steel);
  line-height: 1.4;
}

.client-avatar-large {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--paper);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  font-weight: 700;
  flex-shrink: 0;
}

.graph-card {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
  background: white;
  margin-bottom: 24px;
}

.graph-controls {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
}

.toggle-group {
  display: flex;
  gap: 4px;
  background: var(--paper-raised);
  border-radius: 8px;
  padding: 3px;
}

.toggle-btn {
  background: none;
  border: none;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 0.78rem;
  cursor: pointer;
  color: var(--steel);
}

.toggle-btn.active {
  background: var(--ink);
  color: var(--paper);
}

.week-switcher {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.week-switcher .toggle-btn {
  border: 1px solid var(--border);
  background: white;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.week-current-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--good);
  display: inline-block;
}

.strength-progress-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  text-align: left;
}

.graph-empty {
  color: var(--steel);
  font-size: 0.88rem;
  font-style: italic;
  padding: 40px 0;
  text-align: center;
}

.line-chart {
  width: 100%;
  height: 220px;
}

.chart-axis {
  stroke: var(--border);
  stroke-width: 1;
}

.chart-area {
  fill: var(--accent);
  opacity: 0.08;
}

.chart-line {
  fill: none;
  stroke: var(--accent-ink);
  stroke-width: 2;
}

.chart-dot {
  fill: var(--accent-ink);
}

.chart-endpoint-label {
  font-size: 11px;
  font-family: ui-monospace, monospace;
  fill: var(--ink);
  text-anchor: middle;
}

.chart-gridline {
  stroke: var(--border);
  stroke-width: 1;
  stroke-dasharray: 3 3;
}

.chart-ylabel {
  font-size: 10px;
  font-family: ui-monospace, monospace;
  fill: var(--steel);
}

.chart-xlabel {
  font-size: 10px;
  font-family: ui-monospace, monospace;
  fill: var(--steel);
}

.section-tabs {
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: white;
}

.tab-bar {
  display: flex;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  background: var(--paper-raised);
}

.tab-item {
  background: none;
  border: none;
  padding: 14px 18px;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--steel);
  cursor: pointer;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
}

.tab-item.active {
  color: var(--ink);
  border-bottom-color: var(--accent-ink);
}

.tab-panel {
  padding: 22px;
}

.not-built-panel {
  padding: 20px 0;
}

.field-row {
  display: flex;
  gap: 10px;
  font-size: 0.9rem;
}

.start-form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
}

.start-form-grid label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 0.78rem;
  color: var(--steel);
}

.start-form-grid input,
.start-form-grid select {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 7px 9px;
  font-size: 0.9rem;
  color: var(--ink);
  font-family: inherit;
}

.start-form-grid input:disabled {
  background: var(--paper-raised);
  color: var(--steel);
}

.goal-checkbox {
  width: 20px;
  height: 20px;
  border-radius: 5px;
  border: 1px solid var(--border);
  color: var(--paper);
  font-size: 0.72rem;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
}

.field-label {
  color: var(--steel);
  min-width: 90px;
}

.invoice-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 20px;
}

.invoice-row {
  display: flex;
  align-items: center;
  gap: 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
}

.invoice-desc {
  font-size: 0.88rem;
  font-weight: 600;
}

.invoice-amount {
  font-family: ui-monospace, monospace;
  font-size: 0.88rem;
  margin-left: auto;
}

.status-select {
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 4px 10px;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
}

.status-unpaid { background: #f0d9c4; color: var(--accent-plate); }
.status-sent { background: #dfe6ee; color: var(--accent-ink); }
.status-paid { background: #E8F5E9; color: var(--good); }
.status-due { background: #f3d2d2; color: #C62828; }

.add-invoice-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  padding-top: 16px;
  border-top: 1px dashed var(--border);
}

.add-invoice-form input,
.add-invoice-form select {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 8px;
  font-size: 0.82rem;
}

.add-invoice-form input[name="description"] {
  flex: 1;
  min-width: 200px;
}

/* "Add a ___" builder rows (Daily/Weekly Tracker metrics, Photo slots,
   Invoices, etc.): stretch inputs/selects to fill the card instead of
   leaving the natural (small) input widths bunched on the left with blank
   space after them. */
.add-metric-form input,
.add-metric-form select {
  flex: 1;
  min-width: 120px;
}

.add-metric-form button {
  flex: 0 0 auto;
}

/* ---- Client app shell: renders /client as a phone-frame mock, with a
   sticky app header and bottom tab bar, so viewing it in a desktop browser
   during development already reads as "an app" rather than a web page. On
   an actual phone-width viewport the frame just fills the screen. ---- */

.phone-frame {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2b2d24;
  padding: 40px 12px;
}

/* iPhone 16-proportioned shell: 393x852pt aspect ratio, tall pill-radius
   corners, a dynamic-island cutout floating over the header, and a couple
   of hardware-accent details (side buttons) so it reads as a real device
   rather than a generic rounded rectangle. */
.app-screen {
  width: min(393px, calc(100vw - 24px));
  height: min(852px, calc((100vw - 24px) * 852 / 393), calc(100vh - 80px));
  aspect-ratio: 393 / 852;
  background: var(--paper);
  border-radius: 55px;
  border: 12px solid #333333;
  box-shadow:
    0 30px 60px rgba(0, 0, 0, 0.4),
    inset 0 0 0 2px #2a2b24;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  font-family: var(--font-sans);
}

/* Dynamic island — floats above the header content, doesn't take up any
   flex space of its own. */
.app-screen::before {
  content: "";
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  width: 100px;
  height: 30px;
  background: #0b0c09;
  border-radius: 999px;
  z-index: 20;
  pointer-events: none;
}

.app-header {
  flex-shrink: 0;
  padding: 56px 20px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--paper);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.app-header-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-serif, inherit);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}


.app-header-brand-img {
  height: 30px;
  width: auto;
  max-width: 180px;
  object-fit: contain;
}

.app-header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.app-header-icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: white;
  color: var(--ink);
  cursor: pointer;
  flex-shrink: 0;
}

.app-header-icon-badge {
  position: absolute;
  top: 6px;
  right: 7px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent);
  border: 1.5px solid white;
}

.app-header-icon-btn:hover {
  background: var(--paper-raised);
}

/* Pushed full-screen views (currently: chat) — a slim back-only header
   instead of the brand/icon row, and content flush to the edges since
   chat manages its own inner padding via .chat-panel/.chat-thread. */
.app-push-header {
  flex-shrink: 0;
  padding: 52px 16px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--paper);
  display: flex;
  align-items: center;
  gap: 10px;
}

.app-back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: none;
  background: none;
  color: var(--ink);
  cursor: pointer;
  flex-shrink: 0;
}

.app-back-btn:hover {
  background: var(--paper-raised);
}

.app-push-header-avatar {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: var(--paper-raised);
  color: var(--accent-ink);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-serif);
  font-weight: 700;
  font-size: 0.95rem;
}

.app-push-header-identity {
  flex: 1;
  min-width: 0;
}

.app-push-header-name {
  font-weight: 700;
  font-size: 0.94rem;
}

.app-push-header-sub {
  color: var(--steel);
  font-size: 0.72rem;
}

.app-chat-banner {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: white;
  border-bottom: 1px solid var(--border);
  font-size: 0.78rem;
  color: var(--steel);
}

.app-chat-banner-icon {
  flex-shrink: 0;
  color: var(--steel);
}

.app-content-flush {
  padding: 0 !important;
  display: flex;
  flex-direction: column;
}

.app-content-flush .chat-panel {
  flex: 1;
  min-height: 0;
  padding: 14px 16px;
}

.app-content-flush .chat-thread {
  flex: 1;
  overflow-y: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.app-content {
  flex: 1;
  overflow-y: auto;
  padding: 18px 18px 24px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* old Edge */
}

/* A real phone has no visible scrollbar track — the desktop mock
   shouldn't either, since it reads as chrome rather than app UI. */
.app-content::-webkit-scrollbar,
.app-content-flush .chat-thread::-webkit-scrollbar {
  display: none;
}

.app-lead {
  color: var(--steel);
  margin: 0 0 20px;
  font-size: 0.9rem;
}

.app-bottom-nav {
  flex-shrink: 0;
  display: flex;
  border-top: 1px solid var(--border);
  background: var(--paper);
  padding: 6px 6px calc(env(safe-area-inset-bottom, 0px) + 6px);
}

.app-tab-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 4px;
  border: none;
  background: none;
  border-radius: 12px;
  color: var(--steel);
  font-size: 0.68rem;
  font-weight: 600;
  cursor: pointer;
}

.app-tab-btn:hover {
  background: var(--paper-raised);
}

.app-tab-btn.active {
  color: var(--ink);
}

.app-tab-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
}

/* ---- Chat and Notifications (client only): a dark, Full Potential-branded
   pushed screen — scoped entirely under .cn-screen so it doesn't touch the
   shared (still light) .chat-panel/.chat-bubble rules admin's ChatPanel
   still uses (see "Chat (shared by client + coach)" below), or the rest of
   the still-light client app. ---- */

.cn-screen {
  --font-sans: var(--font-archivo), "Archivo", -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, sans-serif;
  font-family: var(--font-sans);
  background: #F5F5F5;
  color: #333333;
}

.cn-header {
  flex-shrink: 0;
  padding: 52px 18px 14px;
  background: #F5F5F5;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
}

.cn-icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  border-radius: 999px;
  border: 0;
  background: transparent;
  color: #333333;
  cursor: pointer;
}

.cn-icon-btn:hover {
  background: transparent;
}

.cn-badge {
  position: absolute;
  top: 9px;
  right: 10px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #00897B;
  border: 1.5px solid #F5F5F5;
}

.cn-header-titles {
  flex: 1;
  min-width: 0;
  text-align: center;
}


.cn-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #333333;
  line-height: 1.15;
}

.cn-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  color: #333333;
  overflow: hidden;
  font-family: var(--font-sans);
}

/* ---- Chat sub-view ---- */

.cn-chat {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.cn-callbar {
  flex-shrink: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 0 18px 14px;
  border-bottom: 1px solid #EEEEEE;
}

.cn-callbar-label {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #757575;
}

.cn-callbar-value {
  font-size: 0.8rem;
  font-weight: 700;
  color: #333333;
}

.cn-thread {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  scrollbar-width: none;
}

.cn-thread::-webkit-scrollbar {
  display: none;
}

.cn-daylabel {
  text-align: center;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #757575;
  padding: 6px 0 12px;
}

.cn-row {
  display: flex;
  margin-bottom: 6px;
}

.cn-row.mine {
  justify-content: flex-end;
}

.cn-row.theirs {
  justify-content: flex-start;
}

.cn-bubble {
  max-width: 80%;
  border-radius: 16px;
  border-bottom-left-radius: 4px;
  padding: 11px 14px;
  background: #F5F5F5;
  border: 1px solid #EEEEEE;
  color: #333333;
}

.cn-row.mine .cn-bubble {
  background: #00897B;
  border-color: #00897B;
  color: #fff;
  border-bottom-left-radius: 16px;
  border-bottom-right-radius: 4px;
}

.cn-bubble-text {
  font-size: 0.9rem;
  white-space: pre-wrap;
  word-break: break-word;
  line-height: 1.45;
}

.cn-bubble-time {
  font-size: 0.66rem;
  color: #757575;
  margin-top: 4px;
}

.cn-row.mine .cn-bubble-time {
  color: rgba(14, 14, 12, 0.65);
}

.cn-bubble-img,
.cn-bubble-video {
  display: block;
  width: 100%;
  max-width: 220px;
  border-radius: 10px;
  margin-bottom: 4px;
}

.cn-bubble-video {
  background: #000;
}

.cn-empty {
  color: #757575;
  font-size: 14px;
  text-align: center;
  padding: 24px 0;
}

/* Reskins the shared ChatComposeForm (also used, unstyled by this, on
   /admin) purely via descendant selectors — its own base rules in the
   "Chat (shared by client + coach)" section below are untouched. */
.cn-compose {
  flex-shrink: 0;
  padding: 12px 18px 18px;
  border-top: 1px solid #EEEEEE;
}

.cn-compose .chat-compose-form {
  gap: 8px;
  align-items: center;
}

.cn-compose .chat-attach-btn {
  width: 44px;
  height: 44px;
  border-color: #2c2c26;
  background: #F5F5F5;
  color: #757575;
}

.cn-compose .chat-attach-btn:hover {
  background: #1b1b16;
  color: #333333;
}

.cn-compose input[type="text"] {
  height: 44px;
  border: 1px solid var(--fp-input);
  border-radius: 999px;
  padding: 0 16px;
  font-size: 0.9rem;
  background: #F5F5F5;
  color: #333333;
}

.cn-compose input[type="text"]::placeholder {
  color: #6b6b62;
}

.cn-compose input[type="text"]:focus {
  outline: none;
  border-color: #00897B;
}

.cn-compose .btn {
  min-width: 44px;
  height: 44px;
  border: none;
  border-radius: 999px;
  padding: 0 16px;
  background: #00897B;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 800;
}

.cn-compose .btn:hover {
  background: #ffffff;
}

/* ---- Notifications, "Clean feed" (9 Oct). Prefix ntf-. The coach's face
   with a badge, the category's colour as --c / --rgb on each row. */
.ntf-nav { grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); }
.ntf-markall { justify-self: end; height: 32px; padding: 0 11px; border: 0; border-radius: 999px; background: #fff; box-shadow: inset 0 0 0 1px #E0E0E0; font: inherit; font-size: 12px; font-weight: 800; white-space: nowrap; color: #1E3A5F; cursor: pointer; }
.ntf-markall.off { color: #BDBDBD; cursor: default; }
.ntf-scroll { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; padding: 10px 16px 60px; background: linear-gradient(180deg, #e3e9f5 0%, #F5F5F5 28%); }
.ntf-day { display: flex; flex-direction: column; gap: 6px; }
.ntf-day-head { display: flex; align-items: center; justify-content: space-between; margin: 0; padding: 6px 4px 2px; font-size: 10.5px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: #757575; }
.ntf-day-new { color: #2f6fd6; }
.ntf-item { display: flex; align-items: flex-start; gap: 12px; width: 100%; margin: 0; padding: 12px; border: 0; border-radius: 18px; background: #fff; font: inherit; color: inherit; text-align: left; cursor: pointer; box-shadow: 0 1px 0 rgba(16, 24, 40, 0.04), 0 14px 24px -20px rgba(var(--rgb), 0.7), inset 0 0 0 1px rgba(var(--rgb), 0.14); transition: background 0.25s ease, box-shadow 0.25s ease; }
.ntf-item.read { background: transparent; box-shadow: none; }
.ntf-item.read:active { background: rgba(255, 255, 255, 0.6); }
.ntf-avatar { position: relative; flex: none; width: 42px; height: 42px; }
.ntf-avatar img, .ntf-avatar-initial { display: flex; align-items: center; justify-content: center; width: 42px; height: 42px; border-radius: 999px; object-fit: cover; }
.ntf-avatar-initial { background: linear-gradient(135deg, #2a3a5c, #333333); color: #fff; font-size: 16px; font-weight: 800; }
.ntf-avatar-sys { display: flex; align-items: center; justify-content: center; width: 42px; height: 42px; border-radius: 14px; background: rgba(91, 100, 114, 0.12); color: #5b6472; }
.ntf-badge { position: absolute; right: -3px; bottom: -3px; display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 999px; background: var(--c); color: #fff; box-shadow: 0 0 0 2px #fff; }
.ntf-item.read .ntf-badge { box-shadow: 0 0 0 2px #F5F5F5; }
.ntf-content { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ntf-top { display: flex; align-items: center; gap: 6px; }
.ntf-cat { font-size: 10.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: var(--c); }
.ntf-time { margin-left: auto; font-size: 11.5px; font-weight: 600; color: #BDBDBD; font-variant-numeric: tabular-nums; }
.ntf-dot { flex: none; width: 8px; height: 8px; border-radius: 999px; background: #2f6fd6; }
.ntf-title { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; font-size: 14.5px; font-weight: 800; line-height: 1.3; color: #333333; }
.ntf-item.read .ntf-title { font-weight: 600; }
.ntf-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; }
.ntf-body { flex: 1; min-width: 0; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; font-size: 12.5px; font-weight: 600; line-height: 1.4; color: #757575; }
.ntf-action { flex: none; margin: -12px 0 -12px; padding: 12px 0; font-size: 12.5px; font-weight: 800; white-space: nowrap; color: var(--c); }
.ntf-action.gone { color: #BDBDBD; }
.ntf-loading { display: flex; align-items: center; justify-content: center; height: 44px; font-size: 12.5px; font-weight: 600; color: #BDBDBD; }
.ntf-empty { display: flex; flex-direction: column; align-items: center; gap: 8px; padding-top: 80px; text-align: center; }
.ntf-empty-bell { display: flex; align-items: center; justify-content: center; width: 56px; height: 56px; border-radius: 999px; background: rgba(30, 58, 95, 0.08); color: #1E3A5F; }
.ntf-empty b { font-size: 17px; font-weight: 800; color: #333333; }
.ntf-empty small { max-width: 270px; font-size: 13.5px; font-weight: 600; line-height: 1.45; color: #757575; text-wrap: pretty; }
@media (prefers-reduced-motion: reduce) { .ntf-item { transition: none; } }

.cn-footnote {
  border-top: 1px solid #EEEEEE;
  margin-top: 22px;
  padding-top: 14px;
  font-size: 0.74rem;
  color: #757575;
}

/* ---- Home Dark (client only): the app shell's header/content/nav go dark
   only while the Home tab is active — Training/Nutrition/Settings haven't
   been redesigned yet and stay on the original light theme (see AppShell's
   isHomeActive). Descendant overrides of the existing light rules, same
   scoping approach as the Chat and Notifications section above. ---- */

/* One top bar on every tab: menu, wordmark, bell. Off-white with navy. On a
   tab that draws its own banner (Training, Nutrition) it floats over the
   banner's top instead, see-through until the page scrolls, then solid while
   the content scrolls under it. --topbar-h is its height, so a banner can
   leave that much room. */
.app-layer-main { position: relative; --topbar-h: 105px; }

.app-header.dark {
  position: relative;
  z-index: 4;
  justify-content: space-between;
  background: #FAFAFA;
  border-bottom-color: #E6EAF0;
  color: #333333;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}

.app-header.dark.overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  box-shadow: 0 8px 20px -16px rgba(20, 35, 70, 0.55);
}

.app-header.dark.clear {
  background: transparent;
  border-bottom-color: transparent;
  box-shadow: none;
}

/* Over a navy banner, white until the page scrolls. */
.app-header.dark.clear.on-dark { color: #fff; }

/* The wordmark sits centred under the island, between the menu and the bell. */
.app-header.dark .app-header-brand {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-brand), var(--font-serif, Georgia, serif);
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: inherit;
}


/* Bare icons, no circle; the 34px box stays as the tap target. */
.app-header.dark .app-header-icon-btn {
  width: 34px;
  height: 34px;
  border: 0;
  background: transparent;
  color: inherit;
}

.app-header.dark .app-header-icon-btn:hover {
  background: transparent;
}

.app-header.dark .app-header-icon-btn svg {
  width: 22px;
  height: 22px;
}

/* Unread: one accent dot on the bell, nothing when there is none. */
.app-header.dark .app-header-icon-badge {
  width: 8px;
  height: 8px;
  border: 0;
  background: currentColor;
}

.app-content.dark {
  background: #FAFAFA;
  padding: 16px 16px 24px;
}

.app-bottom-nav.dark {
  background: var(--fp-bg);
  border-top-color: var(--fp-line);
}

.app-bottom-nav.dark .app-tab-btn {
  color: var(--fp-dim);
}

.app-bottom-nav.dark .app-tab-btn:hover {
  background: var(--fp-raised);
}

/* The tab you are on reads black, the rest stay grey. */
.app-bottom-nav.dark .app-tab-btn.active {
  color: #111418;
}

/* Tracker/Measurements/Photos aren't redesigned yet — kept as an opaque
   light card so they stay legible sitting on the now-dark Home shell. */
.home-subview-panel {
  background: var(--paper);
  color: var(--ink);
  border-radius: 16px;
  padding: 16px;
  margin: 2px 0 16px;
}

.home-dark {
  color: var(--fp-text);
  font-family: var(--font-sans);
}

.home-dark-datebar {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fp-dim);
}

.home-dark-name {
  font-family: var(--font-serif);
  font-size: 1.9rem;
  font-weight: 600;
  color: var(--fp-text);
  line-height: 1.1;
  margin-top: 4px;
}

.home-dark-subrow {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.home-dark-sub {
  font-size: 0.8rem;
  color: var(--fp-dim);
}

/* Goal / phase: the coach's headline for the block, so it reads as one. */
.home-dark-phase {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--fp-text);
  letter-spacing: -0.01em;
}

/* ---- Plan on Home: the header row carries name, phase, weeks left and
   what's next; a chevron on the right folds the full plan out underneath
   as a vertical list per track. ---- */
.home-dark-headrow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.home-dark-headmain { flex: 1; min-width: 0; }

/* ---- Plan rows under the name: one per track, the phase running now
   with a day-by-day progress bar, and what follows it. Track colours
   match the coach's phase timeline. ---- */
.home-plan-rows {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 14px;
}
.home-plan-row { --pr-bg: #efede6; --pr-fg: #4a4a45; }
.home-plan-row.nutrition { --pr-bg: #dff1ef; --pr-fg: #1d7a70; }
.home-plan-row.training { --pr-bg: #e6e4fa; --pr-fg: #3a3390; }
.home-plan-row.lifestyle { --pr-bg: #efede6; --pr-fg: #4a4a45; }
.home-plan-row-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.home-plan-tag {
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 5px;
  background: var(--pr-bg);
  color: var(--pr-fg);
}
.home-plan-name {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--fp-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.home-plan-left {
  flex-shrink: 0;
  font-size: 11.5px;
  font-weight: 800;
  color: var(--pr-fg);
  text-align: right;
}
.home-plan-bar {
  height: 5px;
  border-radius: 999px;
  background: var(--pr-bg);
  margin-top: 7px;
  overflow: hidden;
}
.home-plan-bar-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--pr-fg);
  transition: width 300ms ease;
}
.home-plan-row-foot {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 5px;
  font-size: 11px;
  color: var(--fp-dim);
}
.home-plan-row-foot b { font-weight: 800; color: var(--fp-text); }
.plan-body {
  margin: 12px 0 4px;
  border: 1px solid var(--fp-line);
  border-radius: 14px;
  background: var(--fp-raised);
  overflow: hidden;
}
/* The plan sheet: a fixed label column beside a scrolling week grid. Row
   heights are pinned on .plan-sheet-r-* so both columns stay in step. */
.plan-sheet {
  display: flex;
  align-items: flex-start;
  padding: 10px 0 8px;
}
.plan-sheet-labels {
  flex: 0 0 112px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-left: 12px;
  border-right: 1px solid var(--fp-line);
  z-index: 1;
  background: var(--fp-raised);
}
.plan-strip {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.plan-strip::-webkit-scrollbar { display: none; }
.plan-sheet-weeks {
  display: grid;
  width: max-content;
  column-gap: 0;
  row-gap: 4px;
  padding: 0 10px 0 8px;
  /* One hairline per week column, anchored to the content box so the
     lines land exactly on the column edges. */
  /* Line at the right edge of each column, so the first column has none
     beside the label divider. */
  background-image: linear-gradient(to right, transparent calc(100% - 1px), var(--fp-line) calc(100% - 1px));
  background-repeat: repeat-x;
  background-origin: content-box;
  background-clip: content-box;
  /* Start below the month row (16px) and its gap (4px), so the lines run
     from the week numbers down, not through the month names. */
  background-position: 0 20px;
}
.plan-sheet-r { box-sizing: border-box; }
.plan-sheet-r-month { height: 16px; }
.plan-sheet-r-week { height: 24px; }
.plan-sheet-r-track { height: 50px; }

.plan-sheet-corner-weeks {
  display: flex;
  align-items: flex-end;
  padding-bottom: 5px;
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fp-dim);
}
.plan-sheet-month {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--fp-dim);
  white-space: nowrap;
  padding-left: 2px;
  line-height: 16px;
}
.plan-sheet-week {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--fp-dim);
  text-align: center;
  line-height: 24px;
  border-radius: 6px;
}
.plan-sheet-week.now {
  color: var(--fp-accent-fg);
  background: var(--fp-accent);
}


.plan-sheet-label {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  padding-right: 10px;
  overflow: hidden;
  background: var(--fp-raised);
}
.plan-sheet-label-name {
  font-size: 13px;
  line-height: 16px;
  font-weight: 800;
  color: var(--fp-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.plan-sheet-label-weeks { font-size: 10px; line-height: 12px; font-weight: 700; color: var(--fp-dim); white-space: nowrap; }
.plan-sheet-track-name {
  font-size: 9.5px;
  line-height: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fp-dim);
}
.plan-sheet-cell {
  position: relative;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}
/* A phase is one outlined block: every cell in it carries the top and
   bottom edge, the first and last cells close the ends. The week the
   client is in gets a soft tint inside the outline. */
.plan-sheet-cell.on {
  /* Same treatment as the live week capsule in the coach's rail, spread
     across the cells of one phase. */
  background: color-mix(in srgb, var(--fp-accent) 16%, rgba(255, 255, 255, 0.55));
  border-top: 1px solid color-mix(in srgb, var(--fp-accent) 55%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--fp-accent) 55%, transparent);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.6), 0 2px 8px color-mix(in srgb, var(--fp-accent) 18%, transparent);
}
.plan-sheet-cell.on.first {
  border-left: 1px solid color-mix(in srgb, var(--fp-accent) 55%, transparent);
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
  margin-left: 3px;
}
.plan-sheet-cell.on.last {
  border-right: 1px solid color-mix(in srgb, var(--fp-accent) 55%, transparent);
  border-top-right-radius: 10px;
  border-bottom-right-radius: 10px;
  margin-right: 3px;
}
.plan-sheet-cell.on:not(.first) { box-shadow: inset 1px 0 0 color-mix(in srgb, var(--fp-accent) 22%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.6), 0 2px 8px color-mix(in srgb, var(--fp-accent) 18%, transparent); }
.plan-sheet-cell.on.now { background: color-mix(in srgb, var(--fp-accent) 30%, rgba(255, 255, 255, 0.55)); }
/* The current week as one column, behind the cells and across the row
   gaps, so the highlight runs unbroken from the header to the last track. */
.plan-sheet-nowcol {
  background: var(--fp-accent-tint);
  border-radius: 0;
  z-index: 0;
}
.plan-sheet-month, .plan-sheet-week { position: relative; z-index: 1; }
.plan-sheet-cell-name {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  color: var(--fp-accent);
}

.home-dark-goal {
  font-size: 0.8rem;
  font-weight: 800;
  color: var(--fp-accent);
}

.home-dark-hr {
  height: 1px;
  background: var(--fp-line);
  margin: 18px 0 16px;
}

.home-dark-phase.unset {
  font-weight: 500;
  color: var(--fp-dim);
}

.home-dark-stats {
  display: flex;
  align-items: flex-start;
  gap: 18px;
}

.home-dark-stat {
  flex: 1;
  min-width: 0;
}

.home-dark-stat-divider {
  width: 1px;
  align-self: stretch;
  background: var(--fp-line);
}

.home-dark-stat-label {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fp-dim);
}

.home-dark-stat-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 2px;
}

.home-dark-stat-value {
  font-family: var(--font-serif);
  font-size: 2.4rem;
  font-weight: 600;
  color: var(--fp-text);
  line-height: 1.05;
}

.home-dark-stat-of {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--fp-dim);
}

.home-dark-stat-delta {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--fp-accent);
}

.home-dark-segments {
  display: flex;
  gap: 4px;
  margin-top: 10px;
}

.home-dark-segment {
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: var(--fp-line);
}

.home-dark-segment.filled {
  background: var(--fp-accent);
}

.home-dark-bar {
  width: 100%;
  height: 5px;
  border-radius: 999px;
  background: var(--fp-line);
  margin-top: 10px;
  overflow: hidden;
}

.home-dark-bar-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--fp-accent);
}

.home-dark-stat-caption {
  font-size: 0.72rem;
  color: var(--fp-dim);
  margin-top: 8px;
}

/* ---- Trend carousel: full-bleed swipeable panels ---- */

.trend-carousel-section {
  margin: 14px -18px 0;
}

.trend-carousel {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}

.trend-carousel::-webkit-scrollbar {
  display: none;
}

.trend-slide {
  flex: 0 0 100%;
  scroll-snap-align: center;
  position: relative;
  height: 216px;
}

.line-chart-bleed {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* The chart is drawn behind this block, and on the light ground the accent
   stroke passes straight through the hero numeral and reads as a
   strikethrough. A page-coloured halo lifts the text off the line without
   putting a panel between them. Applied to the whole overlay so the labels
   and the footer row get it too. */
.trend-slide-overlay {
  text-shadow: 0 0 4px var(--fp-bg), 0 0 8px var(--fp-bg), 0 0 14px var(--fp-bg);
  position: absolute;
  inset: 0;
  padding: 6px 18px 14px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
}

.trend-slide-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.trend-slide-name {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fp-dim);
}

.trend-slide-trend {
  font-size: 0.72rem;
  font-weight: 800;
  white-space: nowrap;
}

.trend-slide-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 2px;
}

.trend-slide-value {
  font-family: var(--font-serif);
  font-size: 2.4rem;
  font-weight: 600;
  color: var(--fp-text);
  line-height: 1.05;
}

.trend-slide-unit {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--fp-dim);
}

.trend-slide-foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  font-size: 0.72rem;
  color: var(--fp-dim);
}

.trend-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 0 18px;
  margin-top: -8px;
}

.trend-dot-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  padding: 20px 8px;
  border: none;
  background: none;
  cursor: pointer;
}

.trend-dot {
  display: block;
  height: 5px;
  border-radius: 999px;
  transition: width 0.15s, background 0.15s;
}

/* ---- Progress report body (Settings -> Progress reports) ---- */

.report-card-stats {
  display: flex;
  gap: 18px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.report-card-stat-label {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--fp-dim);
}

.report-card-stat-value {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--fp-text);
  line-height: 1.1;
  margin-top: 2px;
}

.report-card-chart {
  position: relative;
  width: 100%;
  height: 120px;
  margin-top: 16px;
}

.report-card-chart .line-chart-bleed {
  position: static;
  width: 100%;
  height: 100%;
}

.report-card-chart-foot {
  display: flex;
  justify-content: space-between;
  font-size: 0.7rem;
  color: var(--fp-dim);
}

/* ---- Today / Next meeting / Coach notes / Goals — divider rows ---- */

.home-dark-section {
  padding-top: 22px;
}

.home-dark-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.home-dark-section-title {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fp-dim);
}

.home-dark-section-count {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--fp-accent);
}

.home-dark-empty {
  color: var(--fp-dim);
  font-size: 0.85rem;
  margin: 10px 0 0;
}

.home-dark-rows {
  display: flex;
  flex-direction: column;
  margin-top: 6px;
}

.home-dark-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
  border: none;
  border-top: 1px solid var(--fp-line);
  background: none;
  padding: 14px 0;
  cursor: pointer;
  font: inherit;
  color: inherit;
  min-height: 44px;
  width: 100%;
}

.home-dark-row-body {
  min-width: 0;
}

.home-dark-row-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--fp-text);
}

.home-dark-row-detail {
  color: var(--fp-dim);
  font-size: 0.78rem;
  margin-top: 1px;
}

.home-dark-row-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  border: 1.5px solid var(--fp-input);
  color: var(--fp-dim);
}

.home-dark-row-mark svg {
  width: 12px;
  height: 12px;
}

/* Next with your coach: a date block beside the call detail, rather than a
   bare numeral — reads as a diary entry at a glance. */
.home-meeting-row {
  display: flex;
  align-items: stretch;
  gap: 14px;
  border-top: 1px solid var(--fp-line);
  margin-top: 6px;
  padding-top: 14px;
}

.home-meeting-date {
  flex-shrink: 0;
  width: 52px;
  border: 1px solid #2c2c26;
  border-radius: 12px;
  overflow: hidden;
  text-align: center;
}

.home-meeting-month {
  background: var(--fp-accent-tint);
  color: var(--fp-accent);
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 3px 0;
}

.home-meeting-day {
  font-family: var(--font-serif);
  font-size: 1.6rem;
  font-weight: 600;
  color: var(--fp-text);
  line-height: 1.15;
  padding: 2px 0 4px;
}

.home-meeting-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
}

.home-meeting-title-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.home-meeting-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--fp-text);
}

.home-meeting-in {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fp-accent);
}

.home-meeting-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--fp-dim);
  font-size: 0.76rem;
  flex-wrap: wrap;
}

.home-meeting-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.home-meeting-meta-item svg {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
}

.home-dark-goal-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border-top: 1px solid var(--fp-line);
  padding: 13px 0;
}

.home-dark-goal-index {
  font-family: ui-monospace, Menlo, monospace;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--fp-accent);
  margin-top: 3px;
}

.home-dark-goal-text {
  font-size: 0.9rem;
  color: var(--fp-text);
}

/* ---- Training (client only, dark): reuses the same real components
   (TrainingDayCard/SetLogForm/ClientWeekSwitcher) — purely a visual reskin
   via descendant overrides, scoped under .training-dark so admin's
   ProgramBuilder (which shares .week-switcher/.toggle-btn) is untouched. */

.training-dark {
  color: var(--fp-text);
}

.training-dark .app-lead,
.training-dark .empty-note {
  color: var(--fp-dim);
}

.training-dark .week-switcher {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
}

.training-dark .week-switcher::-webkit-scrollbar {
  display: none;
}

.training-dark .week-switcher .toggle-btn {
  flex: none;
  border: 1px solid #2c2c26;
  background: var(--fp-raised);
  color: var(--fp-dim);
  /* Uniform pills: same height for all, and a floor on width so "Week 1"
     and "Week 10" line up with the status slot on the right. */
  min-height: 34px;
  min-width: 92px;
  justify-content: space-between;
}

/* The status slot on every week pill, sized for the largest thing it holds
   (the 15px tick) so the pill doesn't change size with its state. */
.week-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}

.training-dark .week-switcher .toggle-btn.active {
  background: var(--fp-accent);
  color: var(--fp-accent-fg);
  border-color: var(--fp-accent);
}

.training-dark .week-current-dot {
  background: var(--fp-accent);
}

.training-dark .week-switcher .toggle-btn.active .week-current-dot {
  background: var(--fp-accent-fg);
}

.training-dark .week-progress-card {
  border-color: var(--fp-line);
  background: var(--fp-raised);
}

.training-dark .week-progress-label {
  color: var(--fp-dim);
}

.training-dark .week-progress-value {
  color: var(--fp-text);
}

.training-dark .week-progress-ring-inner {
  background: var(--fp-raised);
  color: var(--fp-text);
}

.training-dark .training-day-card {
  border-color: var(--fp-line);
  background: var(--fp-raised);
}

.training-dark .training-day-card-toggle:hover {
  background: var(--fp-raised);
}

.training-dark .training-day-card-name {
  color: var(--fp-text);
}

.training-dark .training-day-card-label {
  color: var(--fp-dim);
}

.training-dark .training-day-progress-pill {
  color: var(--fp-dim);
  background: var(--fp-line);
}

.training-dark .training-day-progress-pill.done {
  color: var(--fp-accent-fg);
  background: var(--fp-accent);
}

.training-dark .training-day-chevron {
  color: var(--fp-dim);
}

.training-dark .training-day-card-body {
  border-top-color: var(--fp-line);
}

.training-dark .training-exercise-row {
  border-top-color: var(--fp-line);
}

.training-dark .training-exercise-row-top strong {
  color: var(--fp-text);
}

.training-dark .training-exercise-target {
  color: var(--fp-text);
  border-color: var(--fp-line);
  background: var(--fp-raised);
}

.training-dark .exercise-coach-note {
  color: var(--fp-dim);
}

.training-dark .video-link {
  color: var(--fp-accent);
}

.training-dark .training-exercise-done {
  color: var(--fp-accent);
}

.training-dark .training-set-table th {
  color: var(--fp-dim);
}

.training-dark .training-set-table td {
  border-top-color: var(--fp-line);
  color: var(--fp-text);
}

.training-dark .training-set-cell-num {
  color: var(--fp-dim);
}

.training-dark .training-goal-row td {
  background: var(--fp-accent-tint);
  color: var(--fp-accent);
}

.training-dark .training-set-cell-action {
  color: var(--fp-accent);
}

.training-dark .training-set-table input {
  border-color: var(--fp-input);
  background: var(--fp-bg);
  color: var(--fp-text);
}

.training-dark .training-set-table input::placeholder {
  color: #6b6b62;
}

.training-dark .training-set-table input:focus {
  outline: none;
  border-color: var(--fp-accent);
}

.training-dark .btn.btn-sm {
  background: var(--fp-accent);
  color: var(--fp-accent-fg);
  border: none;
}

.training-dark .btn.btn-sm:hover {
  background: #ffffff;
}

/* Home's check-ins row: one status line, not a to-do list — Home reports
   whether anything is outstanding and hands off to the Check-in screen, it
   never completes anything itself. */
.home-checkin-row {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
  border: none;
  border-top: 1px solid var(--fp-line);
  background: none;
  padding: 15px 0;
  margin-top: 6px;
  cursor: pointer;
  font: inherit;
  color: inherit;
  min-height: 44px;
}

.home-checkin-body {
  min-width: 0;
}

.home-checkin-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--fp-text);
}

.home-checkin-detail {
  font-size: 0.78rem;
  color: var(--fp-dim);
  margin-top: 1px;
}

.home-checkin-detail.due {
  color: var(--fp-accent);
}

.home-checkin-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: var(--fp-accent-tint);
  color: var(--fp-accent);
}

.home-checkin-mark.due {
