.wo-switch { position: relative; flex: none; width: 38px; height: 22px; border-radius: 999px; background: #E0E0E0; transition: background 0.15s ease; }
.wo-switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: 999px; background: #fff; box-shadow: 0 1px 2px rgba(20, 30, 50, 0.2); transition: transform 0.15s ease; }
