.wo-page { flex: 0 0 100%; min-width: 0; scroll-snap-align: start; overflow-y: auto; padding: 20px 16px 120px; scrollbar-width: none; }
.wo-page::-webkit-scrollbar { display: none; }
.wo-page-inner { display: flex; flex-direction: column; gap: 14px; }
.wo-kicker { font-size: 12px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #757575; }
.wo-ex-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.wo-ex-titles { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
