.wo-round-btn { display: inline-flex; align-items: center; justify-content: center; width: 36px; height: 36px; border: 1px solid #E0E0E0; border-radius: 999px; background: #fff; color: #00897B; text-decoration: none; }
.wo-round-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; }
.wo-swap-btn { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px; border: 1px solid #E0E0E0; border-radius: 999px; background: #fff; color: #333333; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; }
.wo-swap-btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.wo-swap-banner { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 14px; border-radius: 14px; background: #FBF1DF; color: #6b4a12; font-size: 13.5px; line-height: 1.4; }
