.wo-swap-banner button { flex: none; border: 0; background: none; font: inherit; font-size: 13px; font-weight: 700; color: #9a5b0c; cursor: pointer; padding: 6px; }
.wo-targets { display: grid; grid-template-columns: repeat(auto-fit, minmax(72px, 1fr)); border-radius: 16px; background: #E0F2F1; overflow: hidden; }
.wo-target { display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 12px 6px; border-left: 1px solid rgba(8, 31, 92, 0.1); }
.wo-target:first-child { border-left: 0; }
.wo-target small { font-size: 10.5px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: #00897B; }
.wo-target b { font-size: 19px; font-weight: 700; color: #333333; font-variant-numeric: tabular-nums; }
.wo-page .ts-coachnote { margin-top: 0; padding: 12px 14px; border-radius: 16px; background: #fff; border-color: #EEEEEE; }
.wo-page .ts-coachnote-text { font-size: 14.5px; }
/* The video row: the coach asked, the client sent, the coach replied. */
.wo-video { display: flex; align-items: center; gap: 12px; width: 100%; padding: 12px 14px; border: 0; border-radius: 16px; background: #FBF1DF; font: inherit; color: #6b4a12; text-align: left; cursor: pointer; }
.wo-video.sent, .wo-video.replied { background: #E0F2F1; color: #1E3A5F; }
.wo-video-tile { position: relative; flex: none; display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 12px; background: #B7791F; color: #fff; }
.wo-video.sent .wo-video-tile, .wo-video.replied .wo-video-tile { background: #1E3A5F; }
.wo-video-tile svg { width: 22px; height: 22px; }
.wo-video.asked .wo-video-tile::after, .wo-video.unseen .wo-video-tile::after { content: ""; position: absolute; top: -3px; right: -3px; width: 11px; height: 11px; border: 2px solid #FBF1DF; border-radius: 999px; background: #d64545; }
.wo-video.unseen .wo-video-tile::after { border-color: #E0F2F1; }
.wo-video-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.wo-video-main b { font-size: 15px; font-weight: 700; }
.wo-video-main small { font-size: 13px; opacity: 0.85; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wo-video-action { flex: none; font-size: 13px; font-weight: 700; }
/* The sets card: every row can be filled in and ticked, in any order. */
.wo-sets { display: flex; flex-direction: column; padding: 8px 10px 6px; border-radius: 18px; background: #fff; }
.wo-sets-head, .wo-set { display: grid; grid-template-columns: var(--wo-grid, 30px minmax(0, 1fr) minmax(0, 1fr) 40px); align-items: center; gap: 6px; }
.wo-sets-head { padding: 6px 0 8px; font-size: 10px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #9E9E9E; text-align: left; border-bottom: 1px solid #EEEEEE; }
.wo-sets-head > span { padding-left: 2px; }
.wo-sets-head .ts-unit { margin-left: -7px; text-transform: none; letter-spacing: 0.06em; vertical-align: middle; }
.wo-set { padding: 6px 0; border-bottom: 1px solid #EEEEEE; border-radius: 8px; }
.wo-set.logged { background: #F3FAF5; margin: 0 -6px; padding-left: 6px; padding-right: 6px; }
.wo-set-n { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; border-radius: 999px; background: #F5F5F5; color: #757575; font-size: 13px; font-weight: 700; }
.wo-set-n.done { background: #66BB6A; color: #fff; }
.wo-set-n.warm { background: #FBF1DF; color: #9a5b0c; }
.wo-last { min-height: 44px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border: 0; background: none; font: inherit; font-size: 13px; font-weight: 600; color: #757575; font-variant-numeric: tabular-nums; cursor: pointer; padding: 0; text-align: center; }
.wo-last:disabled { cursor: default; color: #BDBDBD; }
