.wo-input { width: 100%; min-width: 0; height: 44px; box-sizing: border-box; padding: 0 2px; border: 0; border-bottom: 1.5px solid transparent; border-radius: 0; background: transparent; font: inherit; font-size: 17px; font-weight: 700; text-align: left; color: #333333; font-variant-numeric: tabular-nums; outline: none; -moz-appearance: textfield; }
.wo-input::-webkit-outer-spin-button, .wo-input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.wo-input:focus { border-bottom-color: #00897B; }
.wo-input::placeholder { color: #BDBDBD; font-weight: 500; }
.wo-set-val { display: block; text-align: left; padding-left: 2px; font-size: 18px; font-weight: 700; color: #2E7D32; font-variant-numeric: tabular-nums; }
.wo-set-blank { display: block; }
.wo-tick { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 44px; border: 1px solid #E0E0E0; border-radius: 12px; background: #fff; color: #BDBDBD; font: inherit; font-size: 18px; font-weight: 700; cursor: pointer; }
.wo-tick.on { background: #66BB6A; border-color: #66BB6A; color: #fff; }
.wo-tick:disabled { opacity: 0.6; cursor: default; }
.wo-sets-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 4px 6px; }
.wo-add-warm { border: 0; background: none; font: inherit; font-size: 14px; font-weight: 700; color: #00897B; cursor: pointer; padding: 6px 0; }
.wo-add-warm:disabled { color: #BDBDBD; cursor: default; }
.wo-sets-count { font-size: 13px; font-weight: 600; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.wo-sets-count.done { color: #2E7D32; font-weight: 700; }
/* Your note. */
.wo-note-add { width: 100%; height: 48px; border: 1px dashed #E0E0E0; border-radius: 14px; background: none; font: inherit; font-size: 14px; font-weight: 700; color: #00897B; cursor: pointer; }
.wo-note { display: flex; flex-direction: column; gap: 4px; width: 100%; padding: 12px 14px; border: 1px solid #EEEEEE; border-radius: 16px; background: #fff; font: inherit; color: #333333; text-align: left; cursor: pointer; }
.wo-note.editing { border: 1.5px solid #00897B; cursor: auto; }
.wo-note-label { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #757575; }
