.wo-note-text { font-size: 14.5px; line-height: 1.4; white-space: pre-wrap; }
.wo-note-input { width: 100%; box-sizing: border-box; border: 0; padding: 0; margin-top: 2px; font: inherit; font-size: 16px; line-height: 1.4; color: #333333; background: transparent; resize: vertical; outline: none; }
.wo-note-foot { display: flex; justify-content: flex-end; gap: 8px; }
.wo-note-cancel { border: 0; background: none; font: inherit; font-size: 13px; font-weight: 700; color: #757575; padding: 8px 10px; cursor: pointer; }
.wo-note-save { border: 0; border-radius: 10px; background: #1E3A5F; color: #fff; font: inherit; font-size: 13px; font-weight: 700; padding: 8px 14px; cursor: pointer; }
/* Previous sessions. */
.wo-history { border-radius: 16px; background: #fff; overflow: hidden; }
.wo-history-head { display: flex; align-items: center; justify-content: space-between; width: 100%; min-height: 48px; padding: 0 14px; border: 0; background: none; font: inherit; font-size: 15px; font-weight: 700; color: #333333; text-align: left; cursor: pointer; }
.wo-history-chev { width: 8px; height: 8px; border-right: 2px solid #9E9E9E; border-bottom: 2px solid #9E9E9E; transform: translateY(-2px) rotate(45deg); transition: transform 0.2s ease; }
.wo-history-chev.up { transform: translateY(2px) rotate(225deg); }
.wo-history-row { display: flex; flex-direction: column; gap: 4px; padding: 10px 14px 12px; border-top: 1px solid #EEEEEE; }
.wo-history-meta { display: flex; justify-content: space-between; gap: 10px; font-size: 12.5px; font-weight: 700; color: #757575; }
.wo-history-sets { font-size: 14.5px; font-weight: 600; color: #333333; font-variant-numeric: tabular-nums; }
/* Wrap up. */
.wo-wrap { gap: 16px; padding-top: 4px; }
.wo-wrap-title { margin: -8px 0 0; font-size: 26px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.1; color: #333333; }
.wo-stats { display: grid; grid-template-columns: repeat(3, 1fr); border-radius: 18px; background: #fff; overflow: hidden; }
.wo-stat { display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 14px 6px; border-left: 1px solid #EEEEEE; }
.wo-stat:first-child { border-left: 0; }
.wo-stat b { font-size: 20px; font-weight: 700; color: #333333; font-variant-numeric: tabular-nums; }
.wo-stat small { font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #757575; }
.wo-checklist { display: flex; flex-direction: column; border-radius: 18px; background: #fff; overflow: hidden; }
.wo-check-row { display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 6px 14px; border: 0; border-top: 1px solid #EEEEEE; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.wo-check-row:first-child { border-top: 0; }
.wo-check-circle { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 999px; background: #F5F5F5; color: #757575; font-size: 12px; font-weight: 700; }
.wo-check-circle.done { background: #66BB6A; color: #fff; }
.wo-check-name { flex: 1; min-width: 0; font-size: 15px; font-weight: 700; color: #333333; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wo-check-status { font-size: 13px; font-weight: 700; color: #BDBDBD; font-variant-numeric: tabular-nums; }
.wo-check-status.done { color: #2E7D32; }
.wo-check-status.part { color: #9a5b0c; }
.wo-coach-note { display: flex; flex-direction: column; gap: 4px; padding: 12px 14px; border-radius: 16px; background: #fff; }
/* The wrap-up's two questions (29 Sep): 1 to 10 each, optional. */
.wo-ask { display: flex; flex-direction: column; gap: 14px; padding: 12px 14px 14px; border-radius: 16px; background: #fff; }
.wo-ask-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.wo-ask-head small { font-size: 12px; color: #9E9E9E; }
.wo-scale { display: flex; flex-direction: column; gap: 6px; }
.wo-scale-head { display: flex; align-items: baseline; justify-content: space-between; }
.wo-scale-head b { font-size: 15px; font-weight: 700; color: #333333; }
.wo-scale-head span { font-size: 12.5px; font-weight: 600; color: #757575; font-variant-numeric: tabular-nums; }
.wo-scale-row { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 4px; }
.wo-scale-dot { height: 38px; padding: 0; border: 0; border-radius: 10px; background: #F5F5F5; font: inherit; font-size: 13.5px; font-weight: 700; color: #757575; font-variant-numeric: tabular-nums; cursor: pointer; }
.wo-scale-dot.in { background: #dbe4f1; color: #1E3A5F; }
.wo-scale-dot.on { background: #1E3A5F; color: #fff; }
.wo-scale-dot:disabled { cursor: default; }
.wo-wrap-missing { margin: -4px 0 0; text-align: center; font-size: 13px; font-weight: 600; color: #757575; }
/* Swipe to end. */
.wo-swipe { position: relative; height: 60px; border-radius: 999px; background: #1E3A5F; overflow: hidden; user-select: none; -webkit-user-select: none; transition: background 0.3s ease; }
.wo-swipe.locked { background: #66BB6A; }
.wo-swipe-fill { position: absolute; top: 0; bottom: 0; left: 0; border-radius: 999px; background: rgba(255, 255, 255, 0.14); pointer-events: none; }
.wo-swipe:not(.dragging) .wo-swipe-fill { transition: width 0.3s cubic-bezier(0.22, 1, 0.36, 1); }
.wo-swipe-label { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 16px; font-weight: 700; color: #fff; pointer-events: none; }
.wo-swipe-handle { position: absolute; top: 4px; left: 4px; display: flex; align-items: center; justify-content: center; width: 52px; height: 52px; border: 0; border-radius: 999px; background: #fff; color: #1E3A5F; cursor: grab; touch-action: none; }
.wo-swipe:not(.dragging) .wo-swipe-handle { transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1); }
.wo-swipe.locked .wo-swipe-handle { color: #2E7D32; cursor: default; }
.wo-swipe-handle svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
/* Editing a finished workout: Save changes where the swipe was, the same pill. */
.wo-save-edit { height: 60px; border: 0; border-radius: 999px; background: #1E3A5F; color: #fff; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; }
.wo-save-edit:disabled { opacity: 0.7; cursor: default; }
/* The dock: previous, the rest timer, next. */
.wo-dock { position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; display: flex; align-items: center; gap: 12px; padding: 12px 16px 28px; background: rgba(255, 255, 255, 0.94); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); border-top: 1px solid #EEEEEE; }
.wo-dock-btn { flex: none; display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border: 1px solid #E0E0E0; border-radius: 999px; background: #fff; color: #1E3A5F; cursor: pointer; }
.wo-dock-btn.next { background: #1E3A5F; border-color: #1E3A5F; color: #fff; }
.wo-dock-btn.next svg { transform: rotate(180deg); }
.wo-dock-btn:disabled { opacity: 0.35; cursor: default; }
.wo-dock-btn svg { width: 20px; height: 20px; }
.wo-rest { flex: 1; display: flex; align-items: center; justify-content: center; gap: 8px; height: 48px; padding: 0 14px; border: 1px solid #E0E0E0; border-radius: 999px; background: #fff; color: #333333; font: inherit; font-size: 14px; font-weight: 700; cursor: pointer; font-variant-numeric: tabular-nums; }
.wo-rest svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.wo-rest.running { background: #1E3A5F; border-color: #1E3A5F; color: #fff; }
.wo-rest.over { color: #7fd68f; }
.wo-rest-stop { padding: 4px 9px; border-radius: 999px; background: rgba(255, 255, 255, 0.18); font-size: 12px; }
/* Bottom sheets: the gym question, the swap. */
.wo-sheet-scrim { position: fixed; inset: 0; z-index: 40; display: flex; align-items: flex-end; background: rgba(8, 15, 35, 0.45); }
.wo-sheet { width: 100%; max-height: 85vh; overflow-y: auto; padding: 10px 20px calc(24px + env(safe-area-inset-bottom, 0px)); border-radius: 26px 26px 0 0; background: #fff; color: #333333; font-family: var(--font-archivo), "Archivo", -apple-system, BlinkMacSystemFont, sans-serif; animation: wo-sheet-in 0.3s cubic-bezier(0.22, 1, 0.36, 1); }
@keyframes wo-sheet-in { from { transform: translateY(40px); opacity: 0; } to { transform: none; opacity: 1; } }
.wo-sheet-grab { display: block; width: 38px; height: 5px; margin: 0 auto 18px; border-radius: 999px; background: #E0E0E0; }
.wo-sheet-title { margin: 0; font-size: 22px; font-weight: 700; color: #333333; }
.wo-sheet-sub { margin: 4px 0 16px; font-size: 14px; color: #757575; }
.wo-sheet-input { width: 100%; box-sizing: border-box; height: 52px; padding: 0 14px; margin-bottom: 12px; border: 1px solid #E0E0E0; border-radius: 14px; background: #F5F5F5; font: inherit; font-size: 16px; color: #333333; outline: none; }
.wo-sheet-input:focus { border-color: #00897B; background: #fff; }
.wo-sheet-btn { width: 100%; height: 56px; border: 0; border-radius: 16px; background: #1E3A5F; color: #fff; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; }
.wo-sheet-btn:disabled { background: #C5CDDB; cursor: default; }
.wo-sheet-text { display: block; width: 100%; margin-top: 10px; padding: 10px; border: 0; background: none; font: inherit; font-size: 14px; font-weight: 700; color: #00897B; cursor: pointer; }
@media (prefers-reduced-motion: reduce) {
  .so-screen, .wo-sheet, .tr-toast { animation: none; }
  .tr-row-dot, .so-pill-dot { animation: none; }
}
@keyframes ws-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
/* The sets card in the workout: the old logging, one active row with boxes. */
.wo-sets.ts-card-flat { padding: 4px 12px 8px; }
.wo-sets .ts-cols { margin-top: 4px; }
.wo-sets .ts-primary { margin-top: 12px; }
.wo-sets .ts-actions { margin-top: 12px; }
.wo-sets .ts-set.warm .ts-circle.warm { background: #FBF1DF; border-color: #FBF1DF; color: #9a5b0c; font-size: 11px; }
.wo-sets .ts-edit.muted { color: #BDBDBD; }
.wo-sets .ts-set .ts-edit { justify-self: center; }
/* The value columns hang off the right: a flexible gap after the set number,
   then one fixed column per figure, then the Edit column. With fewer figures
   the gap grows and the figures stay beside Edit. */
.wo-sets .ts-grid { grid-template-columns: 34px minmax(0, 1fr) repeat(var(--ts-n, 3), 78px) 34px; }
.wo-sets .ts-grid > :nth-child(1) { grid-column: 1; }
.wo-sets .ts-grid > :nth-child(2) { grid-column: 3; }
.wo-sets .ts-grid > :nth-child(3) { grid-column: 4; }
.wo-sets .ts-grid > :nth-child(4) { grid-column: 5; }
.wo-sets .ts-grid > :nth-child(5) { grid-column: 6; }
.wo-sets .ts-grid > :last-child { grid-column: -2 / -1; }
@media (max-width: 360px) { .wo-sets .ts-grid { grid-template-columns: 34px minmax(0, 1fr) repeat(var(--ts-n, 3), 68px) 34px; } }
/* Exercise page head: kicker and the three buttons on one row, the name under, sized like a heading not a poster. */
.wo-ex-head { position: relative; display: flex; flex-direction: column; align-items: stretch; gap: 6px; }
.wo-ex-top { width: 100%; }
.wo-ex-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.wo-ex-tools { margin-top: 0; }
.wo-ex-name { font-size: 19px; }
.wo-ex-menu { top: 44px; right: 0; }
.wo-menu-row:disabled { color: #BDBDBD; cursor: default; }
/* A row with its icon in front: the words start on one line down the menu. */
.wo-menu-row.ico { justify-content: flex-start; }
.wo-menu-ico { flex: none; width: 19px; height: 19px; color: #1E3A5F; }
.wo-menu-row.danger .wo-menu-ico { color: #b3302b; }
.wo-menu-row:disabled .wo-menu-ico { color: #BDBDBD; }
.wo-sets-foot { justify-content: flex-end; }
.wo-targets-wrap { display: flex; flex-direction: column; gap: 6px; }
.wo-targets-label { text-align: center; font-size: 10.5px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: #00897B; }
/* Bare icons on the exercise head: no circle, a touch darker, same 36px hit area. */
