.pc-dot.on { width: 18px; background: var(--ph-color); }

/* B · stack: in line with the other Home cards. */
.pc-stack { display: flex; flex-direction: column; gap: 14px; }
.pc-scard { border-radius: 24px; background: #fff; overflow: hidden; box-shadow: 0 1px 0 rgba(16, 24, 40, 0.04), 0 16px 28px -20px var(--ph-shadow), inset 0 0 0 1px var(--ph-ring); }
.pc-shead { display: flex; align-items: stretch; gap: 12px; width: 100%; padding: 10px 14px 12px 10px; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.pc-thumb { position: relative; flex: none; width: 88px; min-height: 96px; border-radius: 16px; overflow: hidden; background: var(--ph-deep); }
.pc-thumb .pc-icon { position: absolute; left: 6px; bottom: 6px; width: 24px; height: 24px; box-sizing: border-box; border: 2px solid #fff; }
.pc-thumb .pc-icon svg { width: 12px; height: 12px; }
.pc-scol { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; padding-top: 4px; }
.pc-srow { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-width: 0; }
.pc-strack { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ph-ink); }
.pc-sweek { flex: none; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; font-size: 12px; font-weight: 700; color: #9E9E9E; font-variant-numeric: tabular-nums; }
.pc-chev { display: inline-flex; transition: transform 0.25s ease; }
.pc-chev svg { width: 13px; height: 13px; }
.pc-chev.open { transform: rotate(180deg); }
.pc-sname { font-family: var(--font-bricolage), var(--font-archivo), sans-serif; font-size: 22px; font-weight: 800; letter-spacing: -0.01em; line-height: 1.1; color: #1E3A5F; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pc-sdates { font-size: 12px; font-weight: 600; color: #9E9E9E; white-space: nowrap; }
.pc-scard .pc-left { font-size: 12px; }
.pc-sbody-wrap { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.25s ease; }
.pc-sbody-wrap.open { grid-template-rows: 1fr; }
.pc-sbody-clip { min-height: 0; overflow: hidden; }
.pc-sbody { display: flex; flex-direction: column; gap: 8px; margin: 0 10px 10px; padding: 12px 14px; border-radius: 16px; background: var(--ph-soft); }
.pc-sbody .pc-obj-n { background: #fff; }
.pc-snote { margin: 0; padding-top: 8px; border-top: 1px solid rgba(30, 58, 95, 0.06); font-size: 13px; line-height: 1.45; font-style: italic; color: #5A5B75; }
.pc-sopen { align-self: flex-end; padding: 4px 0; border: 0; background: none; font: inherit; font-size: 13px; font-weight: 700; color: var(--ph-ink); cursor: pointer; }

@media (prefers-reduced-motion: reduce) {
  .pc-bar-fill, .pc-bar-knob, .pc-dot, .pc-chev, .pc-sbody-wrap { transition: none; }
}

/* The phase dialog's Objectives and Cover picture fields (admin). */
.pl-obj-list { display: flex; flex-direction: column; gap: 6px; margin: 0; padding: 0; list-style: none; }
.pl-obj-row { display: flex; align-items: center; gap: 6px; }
.pl-obj-row .pl-dlg-input { flex: 1; min-width: 0; }
.pl-obj-n { flex: none; width: 18px; font-size: 12px; font-weight: 700; color: #9E9E9E; text-align: center; font-variant-numeric: tabular-nums; }
.pl-obj-btn { flex: none; width: 26px; height: 26px; border: 0; border-radius: 6px; background: transparent; color: #757575; font: inherit; font-size: 13px; cursor: pointer; }
