.pl-cover.busy { opacity: 0.6; pointer-events: none; }
.pl-cover-preview { position: relative; flex: none; width: 54px; height: 72px; border-radius: 10px; overflow: hidden; background: var(--ph-deep); }
.pl-cover-preview img, .pl-cover-pick img { width: 100%; height: 100%; object-fit: cover; display: block; }
.pl-cover-picks { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.pl-cover-pick { width: 36px; height: 48px; padding: 0; border: 2px solid transparent; border-radius: 8px; overflow: hidden; background: #F5F5F5; cursor: pointer; }
.pl-cover-pick.on { border-color: #1E3A5F; }

/* Home "Your plan" carousel, clean (25 Sep): the Up Next card's photo and
   navy, and the Training banner's frosted white pills (.tr-wk): white text
   on white glass, no track colours. */
.pc-card { background: linear-gradient(180deg, #222222 0%, #1E3A5F 100%); box-shadow: 0 22px 34px -22px rgba(51, 51, 51, 0.55); }
.pc-scrim { background: linear-gradient(180deg, rgba(8, 12, 20, 0.45) 0%, rgba(8, 12, 20, 0.1) 30%, rgba(8, 12, 20, 0.25) 55%, rgba(12, 24, 52, 0.85) 100%); }
.pc-track-chip, .pc-week-chip { background: rgba(255, 255, 255, 0.16); border: 1px solid rgba(255, 255, 255, 0.35); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px); color: #fff; }
.pc-track-chip { padding: 0 12px 0 10px; font-size: 11px; letter-spacing: 0.12em; }
.pc-track-chip .pc-icon { width: auto; height: auto; background: none; }
.pc-track-chip .pc-icon svg { width: 14px; height: 14px; }
.pc-week-chip { padding: 0 12px; font-size: 12.5px; }
.pc-panel { gap: 12px; padding: 16px 16px 14px; background: rgba(255, 255, 255, 0.16); border: 1px solid rgba(255, 255, 255, 0.35); box-shadow: none; -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px); color: #fff; }
.pc-name { font-family: var(--font-archivo), "Archivo", sans-serif; font-size: 28px; font-weight: 700; line-height: 1.1; letter-spacing: -0.015em; color: #fff; }
.pc-left { font-size: 13.5px; font-weight: 700; color: #fff; }
.pc-card .pc-bar { height: 4px; background: rgba(255, 255, 255, 0.22); }
.pc-card .pc-bar-fill { top: -1px; bottom: -1px; background: #fff; box-shadow: none; }
.pc-card .pc-bar-knob { width: 12px; height: 12px; margin: -6px 0 0 -6px; border: 0; background: #fff; box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.22); }
.pc-ends { font-size: 12px; color: rgba(255, 255, 255, 0.72); }
.pc-obj { padding-top: 12px; border-top: 1px solid rgba(255, 255, 255, 0.2); }
.pc-card .pc-obj-label { color: rgba(255, 255, 255, 0.72); }
.pc-card .pc-obj-n { background: rgba(255, 255, 255, 0.2); color: #fff; }
