/* The bar is live: it runs up to today on arrival, a sheen keeps travelling
   forward along it (the Training banner's), and the knob sends out a ring. */
@keyframes pc-fill-in { from { width: 0; } }
@keyframes pc-knob-in { from { left: 0; } }
@keyframes pc-pulse { from { box-shadow: 0 0 0 0 rgba(30, 58, 95, 0.35); } to { box-shadow: 0 0 0 9px rgba(30, 58, 95, 0); } }
@keyframes pc-pulse-light { from { box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.55); } to { box-shadow: 0 0 0 10px rgba(255, 255, 255, 0); } }
.pc-bar-fill { background: linear-gradient(90deg, #1E3A5F 0%, #1E3A5F 35%, #5b80b8 50%, #1E3A5F 65%, #1E3A5F 100%); background-size: 200% 100%; animation: pc-fill-in 1.4s cubic-bezier(0.22, 1, 0.36, 1) 0.15s both, nd-sheen 2.2s linear 1.6s infinite; }
.pc-card .pc-bar-fill { background: linear-gradient(90deg, #fff 0%, #fff 35%, #c9d6ea 50%, #fff 65%, #fff 100%); background-size: 200% 100%; }
.pc-bar-knob { animation: pc-knob-in 1.4s cubic-bezier(0.22, 1, 0.36, 1) 0.15s both, pc-pulse 1.8s ease-out 1.6s infinite; }
.pc-card .pc-bar-knob { animation-name: pc-knob-in, pc-pulse-light; }
@media (prefers-reduced-motion: reduce) {
  .pc-bar-fill, .pc-bar-knob { animation: none; }
}
/* The training card's Start button: the Up Next card's white button, sized for the panel. */
.pc-start { display: flex; align-items: center; gap: 8px; width: 100%; height: 46px; padding: 0 16px; border: 0; border-radius: 14px; background: #fff; color: #333333; font: inherit; font-size: 15px; font-weight: 700; cursor: pointer; transition: transform 0.12s ease; }
