.pc-next-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pc-next-label { font-size: 10.5px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: rgba(255, 255, 255, 0.72); }
.pc-next-name { font-size: 15px; font-weight: 600; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pc-start { flex: none; display: inline-flex; align-items: center; gap: 6px; width: auto; height: 34px; padding: 0 14px; border-radius: 999px; font-size: 13.5px; font-weight: 700; }
