.hm-lt { border-color: rgba(255, 255, 255, 0.9); background: rgba(255, 255, 255, 0.62); -webkit-backdrop-filter: blur(16px) saturate(140%); backdrop-filter: blur(16px) saturate(140%); box-shadow: 0 10px 26px -20px rgba(20, 30, 60, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.9); }
