.cm-menu-list { position: absolute; right: -6px; bottom: calc(100% + 6px); z-index: 20; display: flex; flex-direction: column; min-width: 132px; padding: 4px; border: 1px solid #e3e8f0; border-radius: 12px; background: #fff; box-shadow: 0 14px 30px -14px rgba(20, 30, 60, 0.35); }
.cm-menu-list button { height: 38px; padding: 0 12px; border: 0; border-radius: 8px; background: none; font: inherit; font-size: 14px; font-weight: 600; color: #333333; text-align: left; cursor: pointer; }
