.qa { position: relative; overflow: hidden; border-radius: 24px; padding: 8px; background: linear-gradient(180deg, #222222 0%, #1E3A5F 100%); box-shadow: 0 18px 30px -22px rgba(51, 51, 51, 0.55); font-family: var(--font-archivo), "Archivo", -apple-system, BlinkMacSystemFont, sans-serif; color: #fff; isolation: isolate; }
