.hm-recap-chev svg { width: 16px; height: 16px; }
.hm-recap-chev.open { transform: rotate(180deg); }
.hm-recap-body { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows 0.34s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.22s ease; }
.hm-recap-body.open { grid-template-rows: 1fr; opacity: 1; }
