.hm-recap-text { margin: 0; padding-top: 8px; font-size: 14.5px; line-height: 1.5; color: #333333; white-space: pre-wrap; transform: translateY(-4px); transition: transform 0.34s cubic-bezier(0.22, 1, 0.36, 1); }
