.hm-ev-field textarea.st-details-input { resize: none; line-height: 1.45; }
.hm-ev-shape { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; padding: 3px; border-radius: 10px; background: #E0F2F1; }
.hm-ev-shape button { min-height: 32px; border: 0; border-radius: 8px; background: none; font: inherit; font-size: 13px; font-weight: 700; color: #757575; cursor: pointer; }
.hm-ev-shape button.on { background: #fff; color: #1E3A5F; box-shadow: 0 1px 2px rgba(51, 51, 51, 0.08); }
.hm-ev-dates { display: flex; gap: 10px; }
.hm-ev-dates .hm-ev-field { flex: 1; min-width: 0; }
.hm-ev-save { min-height: 48px; border: 0; border-radius: 12px; background: #1E3A5F; font: inherit; font-size: 14px; font-weight: 700; color: #fff; cursor: pointer; }
.hm-ev-save:disabled { opacity: 0.45; cursor: default; }
.hm-ev-remove { min-height: 44px; border: 0; border-radius: 12px; background: #fff; font: inherit; font-size: 14px; font-weight: 700; color: #C62828; cursor: pointer; }
