.chat-plus-menu { position: absolute; left: 0; bottom: calc(100% + 8px); z-index: 9; width: 200px; padding: 6px; border-radius: 16px; background: #fff; color: #333333; box-shadow: 0 20px 50px -14px rgba(8, 31, 92, 0.45); }
/* Every row the same: one line, 44px, the icon in its own 20px column. */
.chat-plus-row { display: grid; grid-template-columns: 20px 1fr auto; align-items: center; gap: 12px; width: 100%; height: 44px; padding: 0 12px; border: 0; border-radius: 12px; background: none; font: inherit; font-size: 14.5px; font-weight: 600; line-height: 1; color: #333333; text-align: left; white-space: nowrap; cursor: pointer; }
