/* Charging (9 Oct): with a phase on the way, soft light rises through the
   card like an aura, so it reads as something powering up. Two blurred blobs
   drift up and fade, on transform and opacity only; still under reduced motion. */
.hm-gap.charging { position: relative; overflow: hidden; isolation: isolate; transform: translateZ(0); }
.hm-gap.charging::before, .hm-gap.charging::after { content: ""; position: absolute; inset: -30% -20%; z-index: -1; pointer-events: none; filter: blur(18px); will-change: transform, opacity; }
.hm-gap.charging::before { background: radial-gradient(closest-side at 28% 75%, rgba(120, 196, 255, 0.95), transparent), radial-gradient(closest-side at 78% 85%, rgba(255, 255, 255, 0.55), transparent); animation: hm-aura-a 4.5s ease-in-out infinite; }
.hm-gap.charging::after { background: radial-gradient(closest-side at 62% 80%, rgba(90, 170, 255, 0.85), transparent), radial-gradient(closest-side at 15% 90%, rgba(255, 255, 255, 0.45), transparent); animation: hm-aura-b 6s ease-in-out infinite; animation-delay: -2.5s; }
@keyframes hm-aura-a { 0%, 100% { transform: translate3d(0, 18%, 0) scale(1); opacity: 0.6; } 50% { transform: translate3d(-6%, -18%, 0) scale(1.2); opacity: 1; } }
@keyframes hm-aura-b { 0%, 100% { transform: translate3d(0, 20%, 0) scale(1.05); opacity: 0.5; } 50% { transform: translate3d(7%, -20%, 0) scale(1.25); opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .hm-gap.charging::before, .hm-gap.charging::after { animation: none; opacity: 0.7; } }

/* The Meetings screen, "Agreements first" (9 Oct). Prefix mt-. A sibling of
   the Events screen: same page, rails, type colours (--c / --rgb) and coach
   face. Blue #2f6fd6 is the check-in and the next call's accent. */
.mt-scroll { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; padding: 10px 16px 60px; background: linear-gradient(180deg, #e3e9f5 0%, #F5F5F5 28%); }

/* ---- The next call. */
.mt-next { position: relative; display: flex; align-items: center; gap: 14px; padding: 14px; border-radius: 24px; background: #fff; box-shadow: 0 1px 0 rgba(16, 24, 40, 0.04), 0 20px 34px -24px rgba(30, 58, 95, 0.6), inset 0 0 0 1px rgba(30, 58, 95, 0.1); }
.mt-next.empty { flex-direction: column; align-items: flex-start; gap: 3px; padding: 16px; }
.mt-next.empty b { font-size: 15px; font-weight: 800; color: #333333; }
.mt-next.empty small { font-size: 12.5px; font-weight: 600; color: #757575; }
/* Asking for a call (9 Oct). */
.mt-ask-btn { align-self: stretch; margin-top: 10px; height: 46px; border: 0; border-radius: 14px; background: #1E3A5F; color: #fff; font: inherit; font-size: 14px; font-weight: 800; cursor: pointer; box-shadow: 0 12px 22px -12px rgba(30, 58, 95, 0.9); }
.mt-ask-link { align-self: flex-start; margin-top: -6px; height: 40px; padding: 0 4px; border: 0; background: none; font: inherit; font-size: 12.5px; font-weight: 800; color: #2f6fd6; cursor: pointer; }
.mt-ask { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-radius: 20px; background: #eef3fc; box-shadow: inset 0 0 0 1px rgba(47, 111, 214, 0.22); }
.mt-ask-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.mt-ask-text b { font-size: 14px; font-weight: 800; color: #333333; }
.mt-ask-text small { font-size: 12.5px; font-weight: 600; color: #3b4a66; overflow-wrap: anywhere; }
.mt-ask-x { flex: none; height: 34px; padding: 0 12px; border: 0; border-radius: 10px; background: #fff; font: inherit; font-size: 12.5px; font-weight: 800; color: #757575; cursor: pointer; box-shadow: inset 0 0 0 1px #E0E0E0; }
.mt-ask-x:disabled { opacity: 0.5; }
.mt-asksheet { gap: 14px; }
.mt-ask-err { margin: 0; font-size: 12.5px; font-weight: 700; color: #C62828; }
.mt-ask-hint { text-align: center; font-size: 12px; font-weight: 600; color: #9E9E9E; }
.mt-next-open { flex: 1; min-width: 0; display: flex; align-items: center; gap: 14px; margin: 0; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
.mt-tile { flex: none; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 64px; height: 72px; border-radius: 18px; background: linear-gradient(160deg, #2f6fd6, #1E3A5F); color: #fff; line-height: 1; box-shadow: 0 10px 18px -10px rgba(30, 58, 95, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.25); }
.mt-tile small { font-size: 10px; font-weight: 800; letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.75); }
