.mt-pulse { width: 6px; height: 6px; border-radius: 999px; background: #2f6fd6; animation: mt-pulse 1.6s ease-in-out infinite; }
@keyframes mt-pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(47, 111, 214, 0.5); } 50% { box-shadow: 0 0 0 5px rgba(47, 111, 214, 0); } }
