.mt-card { display: flex; flex-direction: column; border-radius: 18px; background: rgba(255, 255, 255, 0.6); box-shadow: inset 0 0 0 1px #e3e8f0; }
/* The most recent call alone wears its colour. */
/* Landed on from a notification (10 Oct): a flash in the call's colour that fades. */
/* Landed on from a notification (10 Oct): the same light shade Events gives a new row, fading over 600 ms. */
.mt-r.lit .mt-card { animation: mt-lit 600ms ease-out 200ms backwards; }
@keyframes mt-lit { from { background-color: rgba(var(--rgb), 0.14); } to { background-color: rgba(255, 255, 255, 0.6); } }
.mt-card.latest { background: linear-gradient(160deg, rgba(var(--rgb), 0.1), #fff 55%); box-shadow: 0 1px 0 rgba(16, 24, 40, 0.04), 0 14px 24px -20px rgba(var(--rgb), 0.7), inset 0 0 0 1px rgba(var(--rgb), 0.14); }
.mt-head { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 48px; margin: 0; padding: 12px 12px 12px 14px; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
