.mt-clip { min-height: 0; overflow: hidden; }
.mt-in { display: flex; flex-direction: column; gap: 10px; padding: 0 14px 14px; }
.mt-items { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 6px; }
