.mt-check { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; margin-top: 1px; border-radius: 6px; background: #fff; box-shadow: inset 0 0 0 1.5px rgba(var(--rgb), 0.4); color: var(--c); }
.mt-prose { margin: 0; font-size: 13.5px; font-weight: 600; line-height: 1.45; color: #333333; white-space: pre-wrap; }
.mt-linked { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding-top: 10px; border-top: 1px dashed rgba(var(--rgb), 0.25); }
.mt-linked-label { font-size: 10.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: #9E9E9E; }
.mt-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.mt-chip { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 4px; border: 0; border-radius: 999px; background: #fff; box-shadow: inset 0 0 0 1px rgba(var(--ergb), 0.3); font: inherit; font-size: 12px; font-weight: 800; color: #333333; cursor: pointer; }
