.evt-label { height: 12px; line-height: 12px; }
.evt-when { height: 16px; line-height: 16px; }
/* Every item the same height, so the row never changes size as the focus moves; the focused text slides down instead of the gap growing. */
.evt-text { transform: translateY(0); transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1); }
