@keyframes evt-pulse { 0%, 100% { box-shadow: inset 0 0 0 1px var(--c), 0 0 0 0 rgba(var(--rgb), 0.3); } 50% { box-shadow: inset 0 0 0 1px var(--c), 0 0 0 9px rgba(var(--rgb), 0); } }
