@media (prefers-reduced-motion: reduce) { .evt-item, .evt-ring, .evt-title { transition: none; } .evt-item.live .evt-ring { animation: none; } .evt-row { scroll-behavior: auto; } }

/* ---- The Events screen as an itinerary (15 Oct): one 1px spine, thin rings, fine icons, light type, no cards. Prefix evp-. */
.evp-nav { background: #F5F6F8; }
