.ppd-tap:disabled { cursor: default; }
.ppd-card.empty .ppd-tap { background: #fff; outline: 1.5px dashed #C9CFD8; outline-offset: -10px; box-shadow: inset 0 0 0 1px #E1E5EB; }
.ppd-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.ppd-empty { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; color: #8b93a1; font-size: 14px; font-weight: 500; }
.ppd-chip { position: absolute; top: 12px; left: 12px; display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 11px 0 4px; border-radius: 999px; background: rgba(20, 26, 36, 0.42); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); color: #fff; font-size: 12.5px; font-weight: 600; }
.ppd-chip b { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 50%; background: rgba(255, 255, 255, 0.22); font-size: 11px; font-weight: 600; }
.ppd-card.empty .ppd-chip { background: #F5F6F8; color: #141a24; -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: inset 0 0 0 1px #E1E5EB; }
.ppd-card.empty .ppd-chip b { background: #fff; box-shadow: inset 0 0 0 1px #C9CFD8; }
.ppd-foot { position: absolute; left: 12px; right: 12px; bottom: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ppd-state { display: inline-flex; align-items: center; height: 28px; padding: 0 11px; border-radius: 999px; background: rgba(20, 26, 36, 0.42); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); color: #fff; font-size: 12px; font-weight: 600; }
.ppd-state.sent { background: rgba(47, 122, 63, 0.85); }
.ppd-state.ready { background: rgba(20, 26, 36, 0.72); }
.ppd-card.empty .ppd-state, .ppd-state.muted { background: none; color: #8b93a1; padding: 0; -webkit-backdrop-filter: none; backdrop-filter: none; }
.ppd-action { margin-left: auto; display: inline-flex; align-items: center; height: 32px; padding: 0 14px; border-radius: 999px; background: #fff; box-shadow: 0 0 0 1px rgba(20, 26, 36, 0.06); color: #141a24; font-size: 13px; font-weight: 600; }
.ppd-card.empty .ppd-action { background: #141a24; color: #fff; box-shadow: none; }
.ppd-dots { display: flex; justify-content: center; gap: 6px; }
